CREATE OR REPLACE FUNCTION public.acquire_player_rating_refresh(p_game_version text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  head public.player_rating_source_cache%ROWTYPE;
  token UUID;
  v_now TIMESTAMPTZ;
  snapshot JSONB;
BEGIN
  IF p_game_version IS NULL OR p_game_version !~ '^2K[0-9]{2}$' THEN
    RAISE EXCEPTION 'Invalid player rating edition';
  END IF;
  INSERT INTO public.player_rating_source_cache(game_version) VALUES (p_game_version)
    ON CONFLICT DO NOTHING;
  SELECT * INTO head FROM public.player_rating_source_cache
    WHERE game_version = p_game_version FOR UPDATE;
  v_now := clock_timestamp();
  IF head.next_refresh_at <= v_now
     AND (head.lease_expires_at IS NULL OR head.lease_expires_at <= v_now) THEN
    token := gen_random_uuid();
    UPDATE public.player_rating_source_cache SET lease_id = token,
      lease_expires_at = v_now + interval '60 seconds'
      WHERE game_version = p_game_version;
  END IF;
  IF head.version_id IS NOT NULL THEN
    SELECT jsonb_build_object('version_id', v.id, 'revalidated_at', head.revalidated_at,
      'snapshot', v.payload) INTO snapshot
      FROM public.player_rating_source_versions v WHERE v.id = head.version_id;
  END IF;
  RETURN jsonb_build_object('lease_id', token, 'current', snapshot,
    'refresh_in_progress', COALESCE(head.lease_expires_at > v_now AND token IS NULL, false),
    'fresh', COALESCE(head.revalidated_at > v_now - interval '24 hours', false));
END;
$function$;

CREATE OR REPLACE FUNCTION public.advance_qualification_day(p_game_id uuid, p_expected_date date)
 RETURNS TABLE(new_date date, season_complete boolean, result_id uuid, home_team_id uuid, away_team_id uuid, home_score smallint, away_score smallint, winner_team_id uuid, standing_team_id uuid, wins integer, losses integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE g public.games%ROWTYPE; r RECORD; closed BOOLEAN; checked BOOLEAN := false;
BEGIN
  IF auth.uid() IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT * INTO g FROM public.games WHERE id = p_game_id AND user_id = auth.uid()
    AND status = 'active' AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Game not found or access denied'; END IF;
  IF g.simulation_date IS DISTINCT FROM p_expected_date THEN
    new_date := g.simulation_date;
    season_complete := EXISTS (SELECT 1 FROM public.postseason_qualifications q
      WHERE q.game_id = g.id AND q.season_year = g.season_year);
    RETURN NEXT; RETURN;
  END IF;
  IF public.freeze_postseason_qualification(g.id) THEN
    new_date := g.simulation_date; season_complete := true; RETURN NEXT; RETURN;
  END IF;
  IF g.simulation_date >= make_date(g.season_year + 1, 4, 15) THEN
    RAISE EXCEPTION 'Regular-season schedule is incomplete at the simulation boundary';
  END IF;
  FOR r IN SELECT * FROM public.advance_regular_season_day(p_game_id, p_expected_date) LOOP
    IF NOT checked THEN
      closed := public.freeze_postseason_qualification(g.id);
      checked := true;
    END IF;
    RETURN QUERY SELECT r.new_date, closed, r.result_id, r.home_team_id, r.away_team_id,
      r.home_score, r.away_score, r.winner_team_id, r.standing_team_id, r.wins, r.losses;
  END LOOP;
END;
$function$;

CREATE OR REPLACE FUNCTION public.advance_regular_season_day(p_game_id uuid, p_expected_date date)
 RETURNS TABLE(new_date date, season_complete boolean, result_id uuid, home_team_id uuid, away_team_id uuid, home_score smallint, away_score smallint, winner_team_id uuid, standing_team_id uuid, wins integer, losses integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE g public.games%ROWTYPE; run_market BOOLEAN;
BEGIN
  IF auth.uid() IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT * INTO g FROM public.games WHERE id = p_game_id AND user_id = auth.uid()
    AND status = 'active' AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Game not found or access denied'; END IF;
  -- Stale retries and terminal no-ops must not generate bids or resolve the market.
  IF g.simulation_date IS DISTINCT FROM p_expected_date OR g.simulation_date >= make_date(g.season_year + 1, 4, 15) THEN
    RETURN QUERY SELECT * FROM public.advance_simulation_day_core(p_game_id, p_expected_date);
    RETURN;
  END IF;
  run_market := g.season_era_id = 'modern' AND (
    EXISTS (SELECT 1 FROM public.free_agency_availability_enrollments WHERE game_id = p_game_id)
    OR EXISTS (SELECT 1 FROM public.free_agency_pending_offers WHERE game_id = p_game_id AND status = 'pending')
  );
  IF run_market THEN PERFORM public.generate_ai_free_agency_offers(p_game_id); END IF;
  -- RETURN QUERY buffers rows; market failure still rolls back sports, standings and clock.
  RETURN QUERY SELECT * FROM public.advance_simulation_day_core(p_game_id, p_expected_date);
  IF run_market THEN PERFORM public.resolve_due_free_agency_market(p_game_id); END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION public.advance_simulation_day(p_game_id uuid, p_expected_date date)
 RETURNS TABLE(new_date date, season_complete boolean, result_id uuid, home_team_id uuid, away_team_id uuid, home_score smallint, away_score smallint, winner_team_id uuid, standing_team_id uuid, wins integer, losses integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE g public.games%ROWTYPE; r RECORD; f public.scheduled_games%ROWTYPE;
  matches public.scheduled_games[] := ARRAY[]::public.scheduled_games[];
  box_score JSONB; seed BIGINT; home_rating SMALLINT; away_rating SMALLINT; checked BOOLEAN := false;
BEGIN
  IF auth.uid() IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT * INTO g FROM public.games WHERE id = p_game_id AND user_id = auth.uid()
    AND status = 'active' AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Game not found or access denied'; END IF;
  season_complete := EXISTS (SELECT 1 FROM public.postseason_results p WHERE p.game_id = g.id AND p.season_year = g.season_year);
  IF g.simulation_date IS DISTINCT FROM p_expected_date OR season_complete THEN
    new_date := g.simulation_date; RETURN NEXT; RETURN;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.postseason_qualifications q
    WHERE q.game_id = g.id AND q.season_year = g.season_year) THEN
    FOR r IN SELECT * FROM public.advance_qualification_day(p_game_id, p_expected_date) LOOP
      IF NOT checked AND EXISTS (SELECT 1 FROM public.postseason_qualifications q
        WHERE q.game_id = g.id AND q.season_year = g.season_year) THEN
        PERFORM public.prepare_play_in(g.id); checked := true;
      END IF;
      RETURN QUERY SELECT r.new_date, false, r.result_id, r.home_team_id, r.away_team_id,
        r.home_score, r.away_score, r.winner_team_id, r.standing_team_id, r.wins, r.losses;
    END LOOP;
    RETURN;
  END IF;
  PERFORM public.prepare_play_in(g.id);
  PERFORM public.prepare_playoffs(g.id);
  new_date := g.simulation_date + 1;
  IF EXISTS (SELECT 1 FROM public.scheduled_games fixture WHERE fixture.game_id = g.id
    AND fixture.season_year = g.season_year AND fixture.competition_phase IN ('play_in', 'playoffs')
    AND fixture.status = 'scheduled' AND fixture.game_date < new_date)
  THEN RAISE EXCEPTION 'Postseason schedule is behind the simulation clock'; END IF;
  FOR f IN SELECT fixture.* FROM public.scheduled_games fixture WHERE fixture.game_id = g.id
    AND fixture.season_year = g.season_year AND fixture.competition_phase IN ('play_in', 'playoffs')
    AND fixture.game_date = new_date AND fixture.status = 'scheduled' ORDER BY fixture.id FOR UPDATE
  LOOP
    box_score := public.simulate_fixture_box_score(f.id);
    IF box_score IS NOT NULL THEN
      f.home_score := (box_score->>'homeScore')::SMALLINT;
      f.away_score := (box_score->>'awayScore')::SMALLINT;
    ELSE
      home_rating := public.get_simulation_team_rating(g.id, f.home_team_id);
      away_rating := public.get_simulation_team_rating(g.id, f.away_team_id);
      seed := ('x' || substr(md5(g.id::TEXT || ':' || new_date::TEXT || ':' || f.home_team_id::TEXT || ':' || f.away_team_id::TEXT), 1, 8))::bit(32)::BIGINT;
      f.home_score := greatest(70, round(105 + (home_rating + 3 - 75) * 0.55 + (mod(abs(seed), 2400) / 100.0 - 12)));
      f.away_score := greatest(70, round(105 + (away_rating - 75) * 0.55 + (mod(abs(seed / 2400), 2400) / 100.0 - 12)));
      IF f.home_score = f.away_score THEN f.away_score := f.away_score - 1; END IF;
    END IF;
    f.winner_team_id := CASE WHEN f.home_score > f.away_score THEN f.home_team_id ELSE f.away_team_id END;
    UPDATE public.scheduled_games SET status = 'completed', home_score = f.home_score,
      away_score = f.away_score, winner_team_id = f.winner_team_id WHERE id = f.id;
    matches := array_append(matches, f);
  END LOOP;
  UPDATE public.games SET simulation_date = new_date, updated_at = now() WHERE id = g.id;
  PERFORM public.prepare_play_in(g.id);
  PERFORM public.prepare_playoffs(g.id);
  season_complete := EXISTS (SELECT 1 FROM public.postseason_results p WHERE p.game_id = g.id AND p.season_year = g.season_year);
  FOREACH f IN ARRAY matches LOOP
    result_id := f.id; home_team_id := f.home_team_id; away_team_id := f.away_team_id;
    home_score := f.home_score; away_score := f.away_score; winner_team_id := f.winner_team_id;
    RETURN NEXT;
  END LOOP;
  IF cardinality(matches) = 0 THEN RETURN NEXT; END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION public.advance_simulation_day_core(p_game_id uuid, p_expected_date date)
 RETURNS TABLE(new_date date, season_complete boolean, result_id uuid, home_team_id uuid, away_team_id uuid, home_score smallint, away_score smallint, winner_team_id uuid, standing_team_id uuid, wins integer, losses integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_game public.games%ROWTYPE;
  v_new_date DATE;
  v_match public.scheduled_games%ROWTYPE;
  v_home_rating SMALLINT;
  v_away_rating SMALLINT;
  v_home_score SMALLINT;
  v_away_score SMALLINT;
  v_winner UUID;
  v_seed BIGINT;
  v_count INTEGER := 0;
  v_box_score JSONB;
BEGIN
  SELECT * INTO v_game FROM public.games WHERE id = p_game_id AND user_id = auth.uid() FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Game not found or access denied'; END IF;
  IF v_game.simulation_date IS DISTINCT FROM p_expected_date THEN
    new_date := v_game.simulation_date;
    season_complete := v_game.simulation_date >= make_date(v_game.season_year + 1, 4, 15);
    RETURN NEXT; RETURN;
  END IF;
  v_new_date := v_game.simulation_date + 1;
  IF v_new_date > make_date(v_game.season_year + 1, 4, 15) THEN
    new_date := v_game.simulation_date; season_complete := true; RETURN NEXT; RETURN;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.scheduled_games WHERE game_id = p_game_id) THEN
    WITH teams_ordered AS (SELECT id, row_number() OVER (ORDER BY nba_id) - 1 AS slot FROM public.teams),
    rounds AS (
      SELECT c, r, 0 AS home_slot, 1 + r % 29 AS away_slot
      FROM generate_series(0, 1) AS cycles(c) CROSS JOIN generate_series(0, 28) AS round_values(r)
      UNION ALL
      SELECT c, r, 1 + (r + k) % 29, 1 + (r - k + 29) % 29
      FROM generate_series(0, 1) AS cycles(c) CROSS JOIN generate_series(0, 28) AS round_values(r)
      CROSS JOIN generate_series(1, 14) AS pairs(k)
    )
    INSERT INTO public.scheduled_games (game_id, game_date, home_team_id, away_team_id)
    SELECT p_game_id, make_date(v_game.season_year, 10, 15) + (((c * 29 + r) * 182 / 57)::INTEGER),
      home.id, away.id FROM rounds
    JOIN teams_ordered home ON home.slot = CASE WHEN c = 0 THEN home_slot ELSE away_slot END
    JOIN teams_ordered away ON away.slot = CASE WHEN c = 0 THEN away_slot ELSE home_slot END;
    INSERT INTO public.league_standings (game_id, team_id)
    SELECT p_game_id, id FROM public.teams ON CONFLICT DO NOTHING;
  END IF;
  FOR v_match IN SELECT * FROM public.scheduled_games
    WHERE game_id = p_game_id AND game_date = v_new_date AND status = 'scheduled' ORDER BY id FOR UPDATE
  LOOP
    v_box_score := public.simulate_fixture_box_score(v_match.id);
    IF v_box_score IS NOT NULL THEN
      v_home_score := (v_box_score->>'homeScore')::SMALLINT;
      v_away_score := (v_box_score->>'awayScore')::SMALLINT;
    ELSE
      v_home_rating := public.get_simulation_team_rating(p_game_id, v_match.home_team_id);
      v_away_rating := public.get_simulation_team_rating(p_game_id, v_match.away_team_id);
      v_seed := ('x' || substr(md5(p_game_id::TEXT || ':' || v_new_date::TEXT || ':' ||
        v_match.home_team_id::TEXT || ':' || v_match.away_team_id::TEXT), 1, 8))::bit(32)::bigint;
      v_home_score := greatest(70, round(105 + (v_home_rating + 3 - 75) * 0.55 +
        (mod(abs(v_seed), 2400) / 100.0 - 12)));
      v_away_score := greatest(70, round(105 + (v_away_rating - 75) * 0.55 +
        (mod(abs(v_seed / 2400), 2400) / 100.0 - 12)));
      IF v_home_score = v_away_score THEN v_away_score := v_away_score - 1; END IF;
    END IF;
    v_winner := CASE WHEN v_home_score > v_away_score THEN v_match.home_team_id ELSE v_match.away_team_id END;
    UPDATE public.scheduled_games SET status = 'completed', home_score = v_home_score,
      away_score = v_away_score, winner_team_id = v_winner WHERE id = v_match.id;
    UPDATE public.league_standings SET wins = league_standings.wins + CASE WHEN team_id = v_winner THEN 1 ELSE 0 END,
      losses = league_standings.losses + CASE WHEN team_id <> v_winner AND team_id IN (v_match.home_team_id, v_match.away_team_id)
        THEN 1 ELSE 0 END
    WHERE game_id = p_game_id AND team_id IN (v_match.home_team_id, v_match.away_team_id);
    new_date := v_new_date; season_complete := false; result_id := v_match.id;
    home_team_id := v_match.home_team_id; away_team_id := v_match.away_team_id;
    home_score := v_home_score; away_score := v_away_score; winner_team_id := v_winner;
    standing_team_id := NULL; wins := NULL; losses := NULL; v_count := v_count + 1; RETURN NEXT;
  END LOOP;
  UPDATE public.games SET simulation_date = v_new_date, updated_at = now() WHERE id = p_game_id;
  IF v_count = 0 THEN new_date := v_new_date; season_complete := false; RETURN NEXT; END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION public.assess_free_agency_offer(p_game_id uuid, p_offer_id uuid)
 RETURNS TABLE(rejection_reason text, score numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE g public.games%ROWTYPE; o public.free_agency_pending_offers%ROWTYPE; f RECORD; quality INTEGER;
BEGIN
  SELECT * INTO g FROM public.games WHERE id = p_game_id AND user_id = auth.uid()
    AND status = 'active' AND season_era_id = 'modern' AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'Owned active modern game required'; END IF;
  SELECT * INTO o FROM public.free_agency_pending_offers WHERE game_id = p_game_id AND id = p_offer_id AND owner_id = auth.uid();
  IF NOT FOUND THEN RAISE EXCEPTION 'Owned game offer not found'; END IF;
  score := 0;
  IF o.status <> 'pending' THEN rejection_reason := 'Offer is not pending';
  ELSIF g.simulation_date < o.due_date THEN rejection_reason := 'Offer is not due';
  ELSIF o.offer_origin = 'human' AND o.team_id IS DISTINCT FROM g.selected_team_id THEN
    rejection_reason := 'Offer team does not match the selected game team';
  ELSIF o.offer_origin = 'ai' AND (o.team_id = g.selected_team_id OR NOT (
    EXISTS (SELECT 1 FROM public.game_player_states s WHERE s.game_id = p_game_id AND s.team_id = o.team_id)
    OR EXISTS (SELECT 1 FROM public.league_standings s WHERE s.game_id = p_game_id AND s.team_id = o.team_id)
  )) THEN rejection_reason := 'AI team does not participate in this game';
  ELSIF o.season <> format('%s-%s', g.season_year, right((g.season_year + 1)::TEXT, 2)) OR o.season <> '2026-27' THEN
    rejection_reason := 'Offer season must match the supported game financial season';
  ELSIF o.annual_salary <= 0 OR o.annual_salary > 9007199254740991 OR o.years NOT BETWEEN 1 AND 5 THEN
    rejection_reason := 'Stored offer terms are outside supported bounds';
  ELSIF NOT public.is_available_free_agent(p_game_id, o.player_id) THEN
    rejection_reason := 'Explicitly enrolled active teamless player without an agreement required';
  END IF;
  IF rejection_reason IS NOT NULL THEN RETURN NEXT; RETURN; END IF;
  SELECT * INTO STRICT f FROM public.get_free_agency_financial_context(p_game_id, o.player_id, o.team_id);
  IF o.annual_salary < f.minimum_salary OR o.annual_salary > f.maximum_salary THEN
    rejection_reason := 'Salary outside verified minimum and maximum';
  ELSIF f.roster_count + 1 > 15 THEN rejection_reason := 'Roster maximum reached';
  ELSIF o.annual_salary > f.cap_room AND o.annual_salary <> f.minimum_salary THEN rejection_reason := 'Offer exceeds cap room';
  ELSE
    SELECT LEAST(100, GREATEST(0, base_rating)) INTO quality FROM public.teams WHERE id = o.team_id;
    score := (o.annual_salary - f.minimum_salary)::NUMERIC / GREATEST(f.minimum_salary, f.maximum_salary) * 60
      + GREATEST(0, 15 - f.roster_count)::NUMERIC / 15 * 25 + quality::NUMERIC / 100 * 15;
  END IF;
  RETURN NEXT;
END;
$function$;

CREATE OR REPLACE FUNCTION public.assign_fixture_season()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.season_year IS NULL THEN
    SELECT season_year INTO NEW.season_year FROM public.games WHERE id = NEW.game_id;
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.decide_offseason_team_option(p_game_id uuid, p_season_year integer, p_player_id uuid, p_decision text)
 RETURNS game_offseason_contracts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE entry public.game_offseason_contracts%ROWTYPE;
BEGIN
  IF p_decision IS NULL OR p_decision NOT IN ('exercise','decline') THEN RAISE EXCEPTION 'Invalid team option decision'; END IF;
  -- Preparation also revalidates the complete immutable snapshot under the game lock.
  PERFORM public.prepare_offseason_contracts(p_game_id,p_season_year);
  SELECT * INTO entry FROM public.game_offseason_contracts WHERE game_id=p_game_id
    AND season_year=p_season_year AND player_id=p_player_id;
  IF NOT FOUND OR entry.classification<>'team_option' OR entry.next_salary IS NULL THEN RAISE EXCEPTION 'Known controlled-team option required'; END IF;
  IF entry.decision IS NOT NULL AND entry.decision<>p_decision THEN RAISE EXCEPTION 'Team option decision is immutable'; END IF;
  IF entry.decision IS NULL THEN
    UPDATE public.game_offseason_contracts SET decision=p_decision,decided_at=now()
      WHERE game_id=p_game_id AND season_year=p_season_year AND player_id=p_player_id RETURNING * INTO entry;
  END IF;
  RETURN entry;
END $function$;

CREATE OR REPLACE FUNCTION public.enforce_game_contract_copy_immutability()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_game_id UUID;
BEGIN
  v_game_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.game_id ELSE NEW.game_id END;
  IF NOT EXISTS (
    SELECT 1
    FROM games
    WHERE id = v_game_id
      AND status = 'initializing'
      AND deleted_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Game contract snapshots may only be changed while the game is initializing';
  END IF;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'Game contract snapshots are immutable';
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.enroll_simulated_free_agents(p_game_id uuid, p_player_ids uuid[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_game games%ROWTYPE;
  v_player_id UUID;
  v_count INTEGER := 0;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service role required'; END IF;
  IF p_player_ids IS NULL OR cardinality(p_player_ids) = 0
     OR cardinality(ARRAY(SELECT DISTINCT unnest(p_player_ids))) <> cardinality(p_player_ids) THEN
    RAISE EXCEPTION 'Explicit unique player ids are required';
  END IF;
  SELECT * INTO v_game FROM games WHERE id = p_game_id FOR UPDATE;
  IF NOT FOUND OR v_game.status NOT IN ('active', 'initializing') OR v_game.season_era_id <> 'modern'
     OR v_game.deleted_at IS NOT NULL
     OR NOT EXISTS (SELECT 1 FROM game_contract_materializations WHERE game_id = p_game_id) THEN
    RAISE EXCEPTION 'Initializing or active game with materialized contract coverage required';
  END IF;
  FOREACH v_player_id IN ARRAY p_player_ids LOOP
    IF NOT EXISTS (SELECT 1 FROM players p WHERE p.id = v_player_id AND p.is_active)
       OR EXISTS (SELECT 1 FROM contracts c WHERE c.game_id = p_game_id AND c.player_id = v_player_id)
       OR EXISTS (SELECT 1 FROM game_contract_agreements a WHERE a.game_id = p_game_id AND a.player_id = v_player_id) THEN
      RAISE EXCEPTION 'Player is inactive or has a current game agreement';
    END IF;
    INSERT INTO game_player_states(game_id, player_id, team_id, is_active)
    VALUES (p_game_id, v_player_id, NULL, true)
    ON CONFLICT (game_id, player_id) DO NOTHING;
    IF NOT EXISTS (SELECT 1 FROM game_player_states s WHERE s.game_id = p_game_id
      AND s.player_id = v_player_id AND s.team_id IS NULL AND s.is_active) THEN
      RAISE EXCEPTION 'Player is not active and teamless in this game';
    END IF;
    INSERT INTO free_agency_availability_enrollments(game_id, player_id, evidence_kind)
    VALUES (p_game_id, v_player_id, 'simulation-bootstrap-enrollment')
    ON CONFLICT (game_id, player_id) DO NOTHING;
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END;
$function$;

CREATE OR REPLACE FUNCTION public.enter_offseason(p_game_id uuid, p_season_year integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE g public.games%ROWTYPE; entry public.game_offseasons%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  SELECT * INTO g FROM public.games WHERE id = p_game_id AND user_id = auth.uid()
    AND status = 'active' AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Game not found or access denied'; END IF;
  IF p_season_year IS NULL OR g.season_year IS DISTINCT FROM p_season_year THEN
    RAISE EXCEPTION 'Season year does not match the current season';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.postseason_results p
    WHERE p.game_id = g.id AND p.season_year = g.season_year) THEN
    RAISE EXCEPTION 'Completed championship required';
  END IF;
  INSERT INTO public.game_offseasons(game_id, season_year) VALUES (g.id, g.season_year)
    ON CONFLICT (game_id, season_year) DO NOTHING;
  SELECT * INTO STRICT entry FROM public.game_offseasons
    WHERE game_id = g.id AND season_year = g.season_year;
  RETURN jsonb_build_object('seasonYear', entry.season_year, 'enteredAt', entry.entered_at);
END;
$function$;

CREATE OR REPLACE FUNCTION public.execute_trade_transactional(p_game_id uuid, p_team_a_id uuid, p_team_b_id uuid, p_assets jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_game games%ROWTYPE;
  v_trade_id UUID;
  v_asset JSONB;
  v_type TEXT;
  v_id UUID;
  v_from UUID;
  v_to UUID;
  v_pick game_pick_inventory%ROWTYPE;
  v_state game_player_states%ROWTYPE;
  v_metadata JSONB;
  v_contract contracts%ROWTYPE;
  v_contract_count INTEGER;
  v_updated_count INTEGER;
BEGIN
  SELECT * INTO v_game FROM games WHERE id = p_game_id AND user_id = auth.uid() FOR UPDATE;
  IF NOT FOUND OR p_team_a_id = p_team_b_id THEN
    RAISE EXCEPTION 'Game or participating teams are invalid';
  END IF;
  IF jsonb_typeof(p_assets) <> 'array' OR jsonb_array_length(p_assets) < 2 THEN
    RAISE EXCEPTION 'A trade requires assets from both teams';
  END IF;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_assets) a WHERE NOT (a ? 'asset_type' AND a ? 'asset_id' AND a ? 'from_team_id'))
    OR (SELECT count(*) FROM jsonb_array_elements(p_assets) a WHERE a->>'from_team_id' = p_team_a_id::TEXT) = 0
    OR (SELECT count(*) FROM jsonb_array_elements(p_assets) a WHERE a->>'from_team_id' = p_team_b_id::TEXT) = 0 THEN
    RAISE EXCEPTION 'Each team must send at least one asset';
  END IF;
  IF (SELECT count(*) FROM jsonb_array_elements(p_assets) a) <> (
    SELECT count(DISTINCT (a->>'asset_type') || ':' || (a->>'asset_id')) FROM jsonb_array_elements(p_assets) a
  ) THEN
    RAISE EXCEPTION 'Duplicate trade asset';
  END IF;

  INSERT INTO executed_trades (game_id, team_a_id, team_b_id)
  VALUES (p_game_id, p_team_a_id, p_team_b_id) RETURNING id INTO v_trade_id;
  FOR v_asset IN SELECT * FROM jsonb_array_elements(p_assets) LOOP
    v_type := v_asset->>'asset_type';
    v_id := (v_asset->>'asset_id')::UUID;
    v_from := (v_asset->>'from_team_id')::UUID;
    v_to := CASE WHEN v_from = p_team_a_id THEN p_team_b_id ELSE p_team_a_id END;
    IF v_from NOT IN (p_team_a_id, p_team_b_id) OR v_type NOT IN ('player', 'pick') THEN
      RAISE EXCEPTION 'Asset does not belong to this trade';
    END IF;
    IF v_type = 'player' THEN
      SELECT * INTO v_state FROM game_player_states
      WHERE game_id = p_game_id AND player_id = v_id FOR UPDATE;
      IF NOT FOUND OR v_state.team_id IS DISTINCT FROM v_from THEN
        RAISE EXCEPTION 'Player ownership is stale or invalid';
      END IF;
      SELECT count(*) INTO v_contract_count FROM contracts
      WHERE game_id = p_game_id AND player_id = v_id;
      IF v_contract_count = 0 AND NOT EXISTS (
        SELECT 1 FROM game_runtime_contracts r WHERE r.game_id = p_game_id AND r.player_id = v_id
      ) THEN
        RAISE EXCEPTION 'Player contract is missing';
      END IF;
      UPDATE game_player_states SET team_id = v_to, updated_at = now() WHERE id = v_state.id;
      IF v_contract_count > 0 THEN
        FOR v_contract IN SELECT * FROM contracts
          WHERE game_id = p_game_id AND player_id = v_id FOR UPDATE LOOP
          IF v_contract.team_id IS DISTINCT FROM v_from THEN
            RAISE EXCEPTION 'Player contract ownership is stale or invalid';
          END IF;
        END LOOP;
        UPDATE contracts SET team_id = v_to, updated_at = now()
        WHERE game_id = p_game_id AND player_id = v_id AND team_id = v_from;
        GET DIAGNOSTICS v_updated_count = ROW_COUNT;
        IF v_updated_count <> v_contract_count THEN
          RAISE EXCEPTION 'Player contract transfer was incomplete';
        END IF;
      END IF;
      v_metadata := jsonb_build_object('player_id', v_id);
    ELSE
      SELECT * INTO v_pick FROM game_pick_inventory
      WHERE game_id = p_game_id AND id = v_id FOR UPDATE;
      IF NOT FOUND OR v_pick.owner_team_id IS DISTINCT FROM v_from OR NOT v_pick.is_transferable THEN
        RAISE EXCEPTION 'Draft pick ownership is stale or invalid';
      END IF;
      SELECT jsonb_build_object('pick_id', p.id, 'draft_year', p.draft_year,
        'draft_round', p.draft_round, 'protection', p.protection,
        'original_team_id', p.original_team_id)
      INTO v_metadata FROM draft_picks p WHERE p.id = v_pick.draft_pick_id;
      UPDATE game_pick_inventory SET owner_team_id = v_to, updated_at = now() WHERE id = v_pick.id;
    END IF;
    INSERT INTO trade_asset_snapshots (executed_trade_id, asset_type, asset_id, from_team_id, to_team_id, metadata)
    VALUES (v_trade_id, v_type, v_id, v_from, v_to, coalesce(v_metadata, '{}'::jsonb));
  END LOOP;
  RETURN v_trade_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.fail_player_rating_refresh(p_game_version text, p_lease_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
  UPDATE public.player_rating_source_cache SET lease_id = NULL, lease_expires_at = NULL,
    next_refresh_at = clock_timestamp() + interval '5 minutes'
    WHERE game_version = p_game_version AND lease_id = p_lease_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.freeze_postseason_qualification(p_game_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE g public.games%ROWTYPE; participants JSONB; results JSONB; conf TEXT; ranked JSONB;
BEGIN
  SELECT * INTO STRICT g FROM public.games WHERE id = p_game_id FOR UPDATE;
  IF EXISTS (SELECT 1 FROM public.postseason_qualifications q
    WHERE q.game_id = g.id AND q.season_year = g.season_year) THEN RETURN true; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.scheduled_games f WHERE f.game_id = g.id
      AND f.season_year = g.season_year AND f.competition_phase = 'regular_season')
    OR EXISTS (SELECT 1 FROM public.scheduled_games f WHERE f.game_id = g.id
      AND f.season_year = g.season_year AND f.competition_phase = 'regular_season'
      AND f.status <> 'completed') THEN RETURN false; END IF;
  IF EXISTS (SELECT 1 FROM public.scheduled_games f WHERE f.game_id = g.id
    AND f.season_year = g.season_year AND f.competition_phase = 'regular_season'
    AND (f.game_date > g.simulation_date OR f.home_score IS NULL OR f.away_score IS NULL
      OR f.home_score = f.away_score OR f.winner_team_id IS DISTINCT FROM
        CASE WHEN f.home_score > f.away_score THEN f.home_team_id ELSE f.away_team_id END))
  THEN RAISE EXCEPTION 'Regular-season results are incomplete or inconsistent'; END IF;
  IF (SELECT count(*) FROM public.league_standings s JOIN public.teams t ON t.id = s.team_id
    WHERE s.game_id = g.id) <> 30
    OR EXISTS (SELECT 1 FROM public.league_standings s JOIN public.teams t ON t.id = s.team_id
      WHERE s.game_id = g.id AND (t.conference IS NULL OR t.conference NOT IN ('East', 'West')))
    OR (SELECT count(*) FROM public.league_standings s JOIN public.teams t ON t.id = s.team_id
      WHERE s.game_id = g.id AND t.conference = 'East') <> 15
  THEN RAISE EXCEPTION 'Qualification requires 15 teams in each conference'; END IF;

  WITH appearances AS (
    SELECT f.home_team_id AS team_id, f.away_team_id AS opponent_id,
      f.home_score > f.away_score AS won, f.home_score - f.away_score AS differential
    FROM public.scheduled_games f WHERE f.game_id = g.id AND f.season_year = g.season_year
      AND f.competition_phase = 'regular_season'
    UNION ALL
    SELECT f.away_team_id, f.home_team_id, f.away_score > f.home_score, f.away_score - f.home_score
    FROM public.scheduled_games f WHERE f.game_id = g.id AND f.season_year = g.season_year
      AND f.competition_phase = 'regular_season'
  ), records AS (
    SELECT s.team_id, t.conference, s.wins, s.losses,
      row_number() OVER (ORDER BY md5(g.id::TEXT || ':' || g.season_year || ':' || s.team_id), s.team_id) AS draw_order,
      count(a.team_id) AS games, count(*) FILTER (WHERE a.won) AS actual_wins,
      count(*) FILTER (WHERE a.won AND opponent.conference = t.conference) AS conference_wins,
      count(*) FILTER (WHERE opponent.conference = t.conference) AS conference_games,
      coalesce(sum(a.differential), 0) AS differential
    FROM public.league_standings s JOIN public.teams t ON t.id = s.team_id
    LEFT JOIN appearances a ON a.team_id = s.team_id
    LEFT JOIN public.teams opponent ON opponent.id = a.opponent_id
    WHERE s.game_id = g.id GROUP BY s.team_id, t.conference, s.wins, s.losses
  ) SELECT (SELECT coalesce(jsonb_agg(jsonb_build_object('teamId', team_id,
      'opponentId', opponent_id, 'won', won)), '[]') FROM appearances),
    jsonb_agg(jsonb_build_object('teamId', team_id, 'conference', conference,
      'wins', wins, 'losses', losses, 'drawOrder', draw_order,
      'conferenceWins', conference_wins, 'conferenceGames', conference_games,
      'differential', differential, 'games', games, 'actualWins', actual_wins))
    INTO results, participants FROM records;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(participants) t
    WHERE (t->>'wins')::INTEGER <> (t->>'actualWins')::INTEGER
      OR (t->>'wins')::INTEGER + (t->>'losses')::INTEGER <> (t->>'games')::INTEGER)
  THEN RAISE EXCEPTION 'Standings do not match stored regular-season results'; END IF;

  FOREACH conf IN ARRAY ARRAY['East', 'West'] LOOP
    SELECT public.rank_postseason_group(jsonb_agg(t), results) INTO ranked
      FROM jsonb_array_elements(participants) t WHERE t->>'conference' = conf;
    INSERT INTO public.postseason_qualifications(game_id, season_year, team_id, conference, seed, wins, losses, draw_order)
    SELECT g.id, g.season_year, (t->>'teamId')::UUID, conf, position,
      (t->>'wins')::INTEGER, (t->>'losses')::INTEGER, (t->>'drawOrder')::INTEGER
    FROM jsonb_array_elements(ranked) WITH ORDINALITY AS ranked_teams(t, position);
  END LOOP;
  RETURN true;
END;
$function$;

CREATE OR REPLACE FUNCTION public.generate_ai_free_agency_offers(p_game_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  g public.games%ROWTYPE; team UUID; player UUID; f RECORD;
  salary BIGINT; offer_id UUID; inserted INTEGER; total INTEGER := 0;
BEGIN
  SELECT * INTO g FROM public.games WHERE id = p_game_id AND user_id = auth.uid()
    AND status = 'active' AND season_era_id = 'modern' AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Owned active modern game required'; END IF;
  FOR team IN SELECT s.team_id FROM public.game_player_states s WHERE s.game_id = p_game_id AND s.team_id IS NOT NULL
    UNION SELECT s.team_id FROM public.league_standings s WHERE s.game_id = p_game_id ORDER BY team_id
  LOOP
    IF team = g.selected_team_id OR EXISTS (SELECT 1 FROM public.free_agency_pending_offers o
      WHERE o.game_id = p_game_id AND o.team_id = team AND o.offer_origin = 'ai' AND o.ai_decision_date = g.simulation_date) THEN CONTINUE; END IF;
    FOR player IN SELECT s.player_id FROM public.game_player_states s JOIN public.players p ON p.id = s.player_id
      WHERE s.game_id = p_game_id AND p.years_of_experience BETWEEN 0 AND 99
        AND public.is_available_free_agent(p_game_id, s.player_id)
        AND NOT EXISTS (SELECT 1 FROM public.free_agency_pending_offers o WHERE o.game_id = p_game_id
          AND o.player_id = s.player_id AND o.team_id = team AND o.status = 'pending') ORDER BY s.player_id
    LOOP
      SELECT * INTO STRICT f FROM public.get_free_agency_financial_context(p_game_id, player, team);
      IF f.roster_count >= 15 THEN EXIT; END IF;
      salary := CASE WHEN f.cap_room >= floor(f.minimum_salary * 1.10)
        THEN LEAST(f.maximum_salary, floor(f.minimum_salary * 1.10)::BIGINT) ELSE f.minimum_salary END;
      offer_id := md5('free-agency-ai-v1:' || p_game_id::TEXT || ':' || g.simulation_date::TEXT || ':' || team::TEXT)::UUID;
      INSERT INTO public.free_agency_pending_offers(id, request_id, owner_id, game_id, player_id, team_id,
        season, annual_salary, years, due_date, offer_origin, ai_decision_date)
      VALUES (offer_id, gen_random_uuid(), g.user_id, p_game_id, player, team,
        format('%s-%s', g.season_year, right((g.season_year + 1)::TEXT, 2)), salary, 1, g.simulation_date + 1, 'ai', g.simulation_date)
      ON CONFLICT (game_id, team_id, ai_decision_date) WHERE offer_origin = 'ai' DO NOTHING;
      GET DIAGNOSTICS inserted = ROW_COUNT;
      total := total + inserted;
      EXIT;
    END LOOP;
  END LOOP;
  RETURN total;
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_free_agency_financial_context(p_game_id uuid, p_player_id uuid)
 RETURNS TABLE(selected_team_id uuid, season_year integer, simulation_date date, salary_cap bigint, payroll bigint, cap_room bigint, roster_count integer, service_years integer, minimum_salary bigint, maximum_salary bigint)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
  SELECT f.* FROM public.get_free_agency_financial_context(p_game_id, p_player_id,
    (SELECT g.selected_team_id FROM public.games g WHERE g.id = p_game_id)) f;
$function$;

CREATE OR REPLACE FUNCTION public.get_free_agency_financial_context(p_game_id uuid, p_player_id uuid, p_team_id uuid)
 RETURNS TABLE(selected_team_id uuid, season_year integer, simulation_date date, salary_cap bigint, payroll bigint, cap_room bigint, roster_count integer, service_years integer, minimum_salary bigint, maximum_salary bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_game public.games%ROWTYPE; v_player public.players%ROWTYPE; v_payroll NUMERIC := 0;
BEGIN
  SELECT g.* INTO v_game FROM public.games g
  WHERE g.id = p_game_id AND g.user_id = auth.uid() AND g.status = 'active'
    AND g.season_era_id = 'modern' AND g.deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'Owned active modern game required'; END IF;
  IF p_team_id IS NULL OR NOT (p_team_id = v_game.selected_team_id
    OR EXISTS (SELECT 1 FROM public.game_player_states s WHERE s.game_id = p_game_id AND s.team_id = p_team_id)
    OR EXISTS (SELECT 1 FROM public.league_standings s WHERE s.game_id = p_game_id AND s.team_id = p_team_id)
  ) THEN RAISE EXCEPTION 'Team does not participate in this game'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.game_contract_materializations m WHERE m.game_id = p_game_id) THEN
    RAISE EXCEPTION 'Materialized contract coverage required';
  END IF;
  SELECT p.* INTO v_player FROM public.players p WHERE p.id = p_player_id AND p.is_active;
  IF NOT FOUND OR v_player.years_of_experience IS NULL OR v_player.years_of_experience NOT BETWEEN 0 AND 99 THEN
    RAISE EXCEPTION 'Active player with known years of service required';
  END IF;
  IF v_game.season_year <> 2026 THEN RAISE EXCEPTION 'Verified minimum salary schedule unavailable for game season'; END IF;
  service_years := LEAST(v_player.years_of_experience, 10);
  minimum_salary := (ARRAY[1357763,2185116,2449421,2537526,2625627,2845883,3066143,3286399,3506659,3524115,3876529]::BIGINT[])[service_years + 1];
  salary_cap := round(140588000 * power(1.1, GREATEST(0, v_game.season_year - 2024)))::BIGINT;
  maximum_salary := floor(salary_cap * CASE WHEN service_years <= 6 THEN 0.25 WHEN service_years <= 9 THEN 0.30 ELSE 0.35 END)::BIGINT;
  IF EXISTS (
    SELECT 1 FROM public.game_player_states s
    LEFT JOIN public.game_active_runtime_contracts r ON r.game_id = s.game_id AND r.player_id = s.player_id
    LEFT JOIN public.game_contract_identities i ON i.game_id = s.game_id AND i.player_id = s.player_id
    LEFT JOIN public.game_contract_agreements a ON a.game_id = s.game_id AND a.player_id = s.player_id
    LEFT JOIN public.game_contract_seasons cs ON cs.game_id = a.game_id AND cs.agreement_id = a.id AND cs.start_year = v_game.season_year
    WHERE s.game_id = p_game_id AND s.team_id = p_team_id AND r.id IS NULL AND (
      (i.player_id IS NOT NULL AND i.cap_treatment = 'standard-cap-and-matching'
        AND (a.id IS NULL OR a.cap_treatment <> 'standard-cap-and-matching' OR cs.id IS NULL OR cs.salary_amount IS NULL))
      OR (a.id IS NOT NULL AND a.cap_treatment = 'standard-cap-and-matching' AND (cs.id IS NULL OR cs.salary_amount IS NULL))
      OR (i.player_id IS NULL AND a.id IS NULL AND NOT EXISTS (
        SELECT 1 FROM public.contracts c WHERE c.game_id = s.game_id AND c.player_id = s.player_id))
    )
  ) THEN RAISE EXCEPTION 'Canonical current-season standard salary context is incomplete'; END IF;
  IF EXISTS (
    SELECT 1 FROM public.contracts c JOIN public.game_player_states s ON s.game_id = c.game_id AND s.player_id = c.player_id
    WHERE c.game_id = p_game_id AND s.team_id = p_team_id AND c.start_year <= v_game.season_year AND c.end_year >= v_game.season_year
      AND NOT EXISTS (SELECT 1 FROM public.game_contract_identities i WHERE i.game_id = c.game_id AND i.player_id = c.player_id)
      AND NOT EXISTS (SELECT 1 FROM public.game_contract_agreements a WHERE a.game_id = c.game_id AND a.player_id = c.player_id)
      AND NOT EXISTS (SELECT 1 FROM public.game_active_runtime_contracts r WHERE r.game_id = c.game_id AND r.player_id = c.player_id)
      AND (COALESCE((ARRAY[c.salary_y1,c.salary_y2,c.salary_y3,c.salary_y4,c.salary_y5])[v_game.season_year-c.start_year+1], -1) < 0)
  ) THEN RAISE EXCEPTION 'Legacy current-season salary context is incomplete'; END IF;
  SELECT COALESCE(sum(cs.salary_amount), 0) INTO v_payroll
  FROM public.game_contract_agreements a
  JOIN public.game_contract_seasons cs ON cs.game_id = a.game_id AND cs.agreement_id = a.id AND cs.start_year = v_game.season_year
  JOIN public.game_player_states s ON s.game_id = a.game_id AND s.player_id = a.player_id AND s.team_id = p_team_id
  WHERE a.game_id = p_game_id AND a.cap_treatment = 'standard-cap-and-matching'
    AND NOT EXISTS (SELECT 1 FROM public.game_active_runtime_contracts r WHERE r.game_id = a.game_id AND r.player_id = a.player_id);
  SELECT v_payroll + COALESCE(sum(r.annual_salary), 0) INTO v_payroll
  FROM public.game_active_runtime_contracts r
  JOIN public.game_player_states s ON s.game_id = r.game_id AND s.player_id = r.player_id AND s.team_id = p_team_id
  WHERE r.game_id = p_game_id AND r.start_year <= v_game.season_year AND r.end_year >= v_game.season_year;
  SELECT v_payroll + COALESCE(sum((ARRAY[c.salary_y1,c.salary_y2,c.salary_y3,c.salary_y4,c.salary_y5])[v_game.season_year-c.start_year+1]), 0)
  INTO v_payroll FROM public.contracts c
  JOIN public.game_player_states s ON s.game_id = c.game_id AND s.player_id = c.player_id AND s.team_id = p_team_id
  WHERE c.game_id = p_game_id AND c.start_year <= v_game.season_year AND c.end_year >= v_game.season_year
    AND NOT EXISTS (SELECT 1 FROM public.game_contract_identities i WHERE i.game_id = c.game_id AND i.player_id = c.player_id)
    AND NOT EXISTS (SELECT 1 FROM public.game_contract_agreements a WHERE a.game_id = c.game_id AND a.player_id = c.player_id)
    AND NOT EXISTS (SELECT 1 FROM public.game_active_runtime_contracts r WHERE r.game_id = c.game_id AND r.player_id = c.player_id);
  SELECT v_payroll + COALESCE(sum((x.salary_by_year ->> v_game.season_year::TEXT)::BIGINT), 0) INTO v_payroll
  FROM public.game_roster_releases x WHERE x.game_id = p_game_id AND x.team_id = p_team_id;
  IF v_payroll < 0 OR v_payroll > 9007199254740991 THEN RAISE EXCEPTION 'Current payroll is outside supported safe integer range'; END IF;
  SELECT count(*)::INTEGER INTO roster_count FROM public.game_player_states s
  LEFT JOIN public.game_contract_identities i ON i.game_id = s.game_id AND i.player_id = s.player_id
  LEFT JOIN public.game_active_runtime_contracts r ON r.game_id = s.game_id AND r.player_id = s.player_id
  WHERE s.game_id = p_game_id AND s.team_id = p_team_id AND s.is_active
    AND (r.id IS NOT NULL OR COALESCE(i.cap_treatment, 'standard-cap-and-matching') NOT IN ('excluded-two-way', 'excluded-inactive'));
  selected_team_id := p_team_id; season_year := v_game.season_year; simulation_date := v_game.simulation_date;
  payroll := v_payroll::BIGINT; cap_room := GREATEST(0, salary_cap - payroll);
  RETURN NEXT;
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_free_agency_market(p_game_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE g public.games%ROWTYPE; ready BOOLEAN; finance RECORD; result JSONB; candidates JSONB;
BEGIN
  IF auth.uid() IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT * INTO g FROM public.games WHERE id = p_game_id AND user_id = auth.uid() AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'Owned game not found'; END IF;
  ready := g.status = 'active' AND g.season_era_id = 'modern' AND g.season_year = 2026
    AND EXISTS (SELECT 1 FROM public.game_contract_materializations m WHERE m.game_id = p_game_id);
  result := jsonb_build_object('game_id', g.id, 'supported', ready, 'context', NULL, 'candidates', '[]'::jsonb,
    'offers', COALESCE((SELECT jsonb_agg(to_jsonb(o) || jsonb_build_object(
      'player_name', concat_ws(' ', p.first_name, p.last_name), 'team_name', t.name) ORDER BY o.created_at DESC, o.id DESC)
      FROM public.free_agency_pending_offers o LEFT JOIN public.players p ON p.id = o.player_id
      LEFT JOIN public.teams t ON t.id = o.team_id WHERE o.game_id = p_game_id AND o.owner_id = auth.uid()), '[]'::jsonb));
  IF NOT ready THEN RETURN result; END IF;
  SELECT f.* INTO finance FROM public.game_player_states s JOIN public.players p ON p.id = s.player_id
    AND p.is_active AND p.years_of_experience BETWEEN 0 AND 99
  CROSS JOIN LATERAL public.get_free_agency_financial_context(p_game_id, p.id, g.selected_team_id) f
  WHERE s.game_id = p_game_id ORDER BY s.player_id LIMIT 1;
  IF NOT FOUND THEN RAISE EXCEPTION 'Active player with known years of service required for market context'; END IF;
  result := jsonb_set(result, '{context}', jsonb_build_object('team_id', finance.selected_team_id,
    'season', format('%s-%s', finance.season_year, right((finance.season_year + 1)::TEXT, 2)),
    'simulation_date', finance.simulation_date, 'salary_cap', finance.salary_cap,
    'payroll', finance.payroll, 'cap_room', finance.cap_room, 'roster_count', finance.roster_count));
  IF EXISTS (SELECT 1 FROM public.game_player_states s JOIN public.players p ON p.id = s.player_id
    WHERE s.game_id = p_game_id AND public.is_available_free_agent(p_game_id, p.id)
      AND (p.years_of_experience IS NULL OR p.years_of_experience NOT BETWEEN 0 AND 99)) THEN
    RAISE EXCEPTION 'Active player with known years of service required';
  END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('player_id', p.id, 'first_name', p.first_name,
    'last_name', p.last_name, 'position', p.position, 'nba_id', p.nba_id, 'espn_id', p.espn_id,
    'minimum_salary', f.minimum_salary, 'maximum_salary', f.maximum_salary)
    ORDER BY p.id), '[]'::jsonb) INTO candidates
  FROM public.game_player_states s JOIN public.players p ON p.id = s.player_id
  CROSS JOIN LATERAL public.get_free_agency_financial_context(p_game_id, p.id, g.selected_team_id) f
  WHERE s.game_id = p_game_id AND public.is_available_free_agent(p_game_id, p.id)
    AND p.years_of_experience BETWEEN 0 AND 99;
  RETURN jsonb_set(result, '{candidates}', candidates);
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_player_season_statistics(p_game_id uuid, p_season_year integer, p_phase text DEFAULT 'regular_season'::text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
  WITH fixtures AS (
    SELECT f.id, b.payload FROM public.scheduled_games f
    LEFT JOIN public.game_box_scores b ON b.game_id = f.game_id AND b.scheduled_game_id = f.id
    WHERE f.game_id = p_game_id AND f.season_year = p_season_year
      AND f.competition_phase = p_phase AND f.status = 'completed'
      AND EXISTS (SELECT 1 FROM public.games g WHERE g.id = f.game_id
        AND g.user_id = auth.uid() AND g.deleted_at IS NULL)
  ), appearances AS (
    SELECT f.id, p FROM fixtures f CROSS JOIN LATERAL jsonb_array_elements(f.payload->'players') p
    WHERE (p->>'seconds')::INTEGER > 0
  ), players AS (
    SELECT p->>'playerId' AS player_id, max(p->>'playerName') AS player_name,
      count(*) AS games_played FROM appearances GROUP BY p->>'playerId'
  ), totals AS (
    SELECT a.p->>'playerId' AS player_id, v.key, sum(v.value::BIGINT) AS total
    FROM appearances a CROSS JOIN LATERAL jsonb_each_text(a.p) v
    WHERE v.key IN ('seconds','fieldGoalsMade','fieldGoalsAttempted','threePointersMade',
      'threePointersAttempted','freeThrowsMade','freeThrowsAttempted','offensiveRebounds',
      'defensiveRebounds','assists','steals','blocks','turnovers','personalFouls','points')
    GROUP BY a.p->>'playerId', v.key
  ), rows AS (
    SELECT jsonb_build_object('playerId', p.player_id, 'playerName', p.player_name,
      'gamesPlayed', p.games_played, 'totals', jsonb_object_agg(t.key, t.total)) AS row
    FROM players p JOIN totals t USING (player_id)
    GROUP BY p.player_id, p.player_name, p.games_played
  )
  SELECT jsonb_build_object('completedGames', (SELECT count(*) FROM fixtures),
    'coveredGames', (SELECT count(payload) FROM fixtures),
    'players', coalesce((SELECT jsonb_agg(row ORDER BY row->>'playerId') FROM rows), '[]'::JSONB));
$function$;

CREATE OR REPLACE FUNCTION public.get_postseason_state(p_game_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE g public.games%ROWTYPE; result JSONB;
BEGIN
  IF auth.uid() IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT * INTO g FROM public.games WHERE id = p_game_id AND user_id = auth.uid() AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'Game not found or access denied'; END IF;
  SELECT jsonb_build_object(
    'phase', CASE WHEN EXISTS (SELECT 1 FROM public.postseason_results p WHERE p.game_id = g.id AND p.season_year = g.season_year) THEN 'complete'
      WHEN (SELECT count(*) FROM public.postseason_playoff_seeds p WHERE p.game_id = g.id AND p.season_year = g.season_year) = 16 THEN 'playoffs'
      WHEN EXISTS (SELECT 1 FROM public.postseason_qualifications q WHERE q.game_id = g.id AND q.season_year = g.season_year) THEN 'play_in'
      ELSE 'regular_season' END,
    'championTeamId', (SELECT p.champion_team_id FROM public.postseason_results p WHERE p.game_id = g.id AND p.season_year = g.season_year),
    'runnerUpTeamId', (SELECT p.runner_up_team_id FROM public.postseason_results p WHERE p.game_id = g.id AND p.season_year = g.season_year),
    'qualification', coalesce((SELECT jsonb_agg(jsonb_build_object('teamId',q.team_id,'conference',q.conference,'seed',q.seed) ORDER BY q.conference,q.seed)
      FROM public.postseason_qualifications q WHERE q.game_id = g.id AND q.season_year = g.season_year),'[]'::JSONB),
    'playoffSeeds', coalesce((SELECT jsonb_agg(jsonb_build_object('teamId',p.team_id,'conference',p.conference,'seed',p.seed) ORDER BY p.conference,p.seed)
      FROM public.postseason_playoff_seeds p WHERE p.game_id = g.id AND p.season_year = g.season_year),'[]'::JSONB),
    'series', coalesce((SELECT jsonb_agg(jsonb_build_object('id',p.id,'round',p.round,'conference',p.conference,'bracketSlot',p.bracket_slot,
      'homeTeamId',p.home_team_id,'awayTeamId',p.away_team_id,'homeWins',p.home_wins,'awayWins',p.away_wins,'winnerTeamId',p.winner_team_id)
      ORDER BY p.round,p.conference,p.bracket_slot) FROM public.postseason_series p WHERE p.game_id = g.id AND p.season_year = g.season_year),'[]'::JSONB),
    'games', coalesce((SELECT jsonb_agg(jsonb_build_object('id',f.id,'seriesId',link.series_id,'stage',pi.stage,
      'conference',coalesce(p.conference,pi.conference),'gameNumber',link.game_number,'gameDate',f.game_date,
      'homeTeamId',f.home_team_id,'awayTeamId',f.away_team_id,'homeScore',f.home_score,'awayScore',f.away_score,
      'winnerTeamId',f.winner_team_id,'status',f.status) ORDER BY f.game_date,f.id)
      FROM public.scheduled_games f LEFT JOIN public.postseason_series_games link ON link.scheduled_game_id = f.id
      LEFT JOIN public.postseason_series p ON p.id = link.series_id
      LEFT JOIN public.postseason_play_in_games pi ON pi.scheduled_game_id = f.id
      WHERE f.game_id = g.id AND f.season_year = g.season_year AND (p.id IS NOT NULL OR pi.scheduled_game_id IS NOT NULL)),'[]'::JSONB)
  ) INTO result;
  RETURN result;
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_roster_release_cap_charge(p_game_id uuid, p_team_id uuid, p_season_year integer)
 RETURNS bigint
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
  SELECT COALESCE(sum((salary_by_year ->> p_season_year::TEXT)::BIGINT), 0)::BIGINT
  FROM public.game_roster_releases WHERE game_id = p_game_id AND team_id = p_team_id;
$function$;

CREATE OR REPLACE FUNCTION public.get_simulation_team_rating(p_game_id uuid, p_team_id uuid)
 RETURNS smallint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  g public.games%ROWTYPE;
  base SMALLINT;
  available INTEGER;
  rated_available INTEGER;
  average_quality NUMERIC;
  quality_adjustment INTEGER := 0;
BEGIN
  SELECT * INTO g FROM public.games WHERE id = p_game_id AND user_id = auth.uid();
  IF NOT FOUND THEN RAISE EXCEPTION 'Game not found or access denied'; END IF;
  SELECT t.base_rating INTO base FROM public.teams t WHERE t.id = p_team_id;
  IF base IS NULL THEN RAISE EXCEPTION 'Simulation team not found'; END IF;
  IF g.season_era_id <> 'modern'
     OR NOT EXISTS (SELECT 1 FROM public.game_contract_materializations m WHERE m.game_id = p_game_id)
     OR NOT EXISTS (SELECT 1 FROM public.game_player_states s WHERE s.game_id = p_game_id) THEN
    RETURN base;
  END IF;
  SELECT count(*)::INTEGER INTO available FROM public.game_player_states s
  WHERE s.game_id = p_game_id AND s.team_id = p_team_id AND s.is_active AND NOT s.is_injured;
  SELECT count(*)::INTEGER,
    avg((a.attributes->>'closeShot')::NUMERIC + (a.attributes->>'midRangeShot')::NUMERIC
      + (a.attributes->>'threePointShot')::NUMERIC + (a.attributes->>'freeThrow')::NUMERIC
      + (a.attributes->>'drawFoul')::NUMERIC + (a.attributes->>'ballHandle')::NUMERIC
      + (a.attributes->>'passAccuracy')::NUMERIC + (a.attributes->>'interiorDefense')::NUMERIC
      + (a.attributes->>'perimeterDefense')::NUMERIC + (a.attributes->>'steal')::NUMERIC
      + (a.attributes->>'block')::NUMERIC + (a.attributes->>'offensiveRebound')::NUMERIC
      + (a.attributes->>'defensiveRebound')::NUMERIC + (a.attributes->>'stamina')::NUMERIC) / 14.0
  INTO rated_available, average_quality
  FROM public.game_player_states s
  JOIN public.game_player_attributes a
    ON a.game_id = s.game_id AND a.season_year = g.season_year AND a.player_id = s.player_id
  WHERE s.game_id = p_game_id AND s.team_id = p_team_id AND s.is_active AND NOT s.is_injured;
  IF rated_available = available AND rated_available > 0 THEN
    quality_adjustment := round((average_quality - 60) * 0.2)::INTEGER;
  END IF;
  RETURN LEAST(100, GREATEST(0,
    base + 2 * (LEAST(available, 15) - 12) + quality_adjustment))::SMALLINT;
END;
$function$;

CREATE OR REPLACE FUNCTION public.guard_game_clock_writes()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF current_user IN ('authenticated', 'anon') AND (
    NEW.user_id IS DISTINCT FROM OLD.user_id
    OR NEW.selected_team_id IS DISTINCT FROM OLD.selected_team_id
    OR NEW.season_year IS DISTINCT FROM OLD.season_year
    OR NEW.season_era_id IS DISTINCT FROM OLD.season_era_id
    OR NEW.simulation_date IS DISTINCT FROM OLD.simulation_date
    OR (NEW.status = 'initializing' AND OLD.status <> 'initializing')
  ) THEN
    RAISE EXCEPTION 'Game ownership, identity, and simulation clock are authoritative';
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.guard_game_player_state_writes()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF current_user NOT IN ('authenticated', 'anon') THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  IF TG_OP = 'DELETE' THEN
    -- Allow existing game-delete cascades, but never direct roster removal.
    IF NOT EXISTS (SELECT 1 FROM public.games WHERE id = OLD.game_id) THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'Direct roster deletion is not permitted';
  END IF;

  IF TG_OP = 'INSERT' THEN
    RAISE EXCEPTION 'Direct roster insertion is not permitted';
  END IF;

  IF (NEW.game_id, NEW.player_id, NEW.team_id, NEW.is_active)
     IS DISTINCT FROM (OLD.game_id, OLD.player_id, OLD.team_id, OLD.is_active) THEN
    RAISE EXCEPTION 'Roster identity, ownership, and eligibility are authoritative';
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.guard_legacy_contract_writes()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF current_user NOT IN ('authenticated', 'anon') THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;
  IF TG_OP = 'DELETE' AND NOT EXISTS (SELECT 1 FROM public.games WHERE id = OLD.game_id) THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'Legacy contract identity and salary are authoritative';
END;
$function$;

CREATE OR REPLACE FUNCTION public.import_initial_free_agents(p_game_id uuid, p_owner_id uuid, p_snapshot jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  g public.games%ROWTYPE;
  prior public.free_agency_imports%ROWTYPE;
  candidate JSONB;
  player public.players%ROWTYPE;
  enrolled INTEGER := 0;
  skipped INTEGER := 0;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Service role required'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('current-roster', 0));
  SELECT * INTO g FROM public.games WHERE id = p_game_id AND user_id = p_owner_id
    AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND OR g.status NOT IN ('active', 'initializing') OR g.season_era_id <> 'modern'
    OR g.season_year <> 2026
    OR NOT EXISTS (SELECT 1 FROM public.game_contract_materializations WHERE game_id = p_game_id) THEN
    RAISE EXCEPTION 'Owned initializing or active materialized modern 2026 game required';
  END IF;
  SELECT * INTO prior FROM public.free_agency_imports WHERE game_id = p_game_id;
  IF FOUND THEN
    RETURN jsonb_build_object('enrolled_count', prior.enrolled_count, 'skipped_count', prior.skipped_count);
  END IF;
  IF p_snapshot IS NULL
    OR p_snapshot->>'sourceUrl' IS DISTINCT FROM 'https://www.nba.com/players/free-agent-tracker/2026'
    OR p_snapshot->>'seasonYear' IS DISTINCT FROM '2026'
    OR jsonb_typeof(p_snapshot->'players') IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'Validated NBA tracker snapshot required';
  END IF;
  IF jsonb_array_length(p_snapshot->'players') NOT BETWEEN 1 AND 1000 THEN
    RAISE EXCEPTION 'Invalid NBA tracker size';
  END IF;
  FOR candidate IN SELECT value FROM jsonb_array_elements(p_snapshot->'players') LOOP
    IF candidate->>'season' IS DISTINCT FROM '2026'
      OR candidate->>'type' IS DISTINCT FROM 'ufa' OR candidate->>'newTeamId' IS DISTINCT FROM '0'
      OR candidate->>'isPlayerOption' IS DISTINCT FROM 'false'
      OR candidate->>'isTeamOption' IS DISTINCT FROM 'false'
      OR candidate->>'isEarlyTerminationOption' IS DISTINCT FROM 'false'
      OR candidate->>'isTwoWayFreeAgent' IS DISTINCT FROM 'false' THEN
      CONTINUE;
    END IF;
    IF (candidate->>'playerId')::INTEGER <= 0 OR (candidate->>'exp')::INTEGER NOT BETWEEN 0 AND 99
      OR NULLIF(trim(candidate->>'playerFirstName'), '') IS NULL
      OR NULLIF(trim(candidate->>'playerLastName'), '') IS NULL
      OR NULLIF(trim(candidate->>'playerDisplayName'), '') IS NULL
      OR candidate->>'position' !~ '^[GFC](-[GFC])?$' THEN
      RAISE EXCEPTION 'Invalid NBA tracker player';
    END IF;
    SELECT * INTO player FROM public.players WHERE nba_id = (candidate->>'playerId')::INTEGER;
    IF NOT FOUND THEN
      IF EXISTS (SELECT 1 FROM public.players p
        WHERE lower(p.full_name) = lower(candidate->>'playerDisplayName')) THEN
        skipped := skipped + 1;
        CONTINUE;
      END IF;
      INSERT INTO public.players(nba_id, first_name, last_name, full_name, position, years_of_experience, is_active)
      VALUES ((candidate->>'playerId')::INTEGER, candidate->>'playerFirstName', candidate->>'playerLastName',
        candidate->>'playerDisplayName', candidate->>'position', (candidate->>'exp')::SMALLINT, true)
      RETURNING * INTO player;
    END IF;
    IF player.team_id IS NOT NULL
      OR EXISTS (SELECT 1 FROM public.game_player_states s WHERE s.game_id = p_game_id
        AND s.player_id = player.id AND (s.team_id IS NOT NULL OR NOT s.is_active))
      OR EXISTS (SELECT 1 FROM public.contracts c WHERE c.game_id = p_game_id AND c.player_id = player.id)
      OR EXISTS (SELECT 1 FROM public.game_contract_agreements a WHERE a.game_id = p_game_id AND a.player_id = player.id)
      OR EXISTS (SELECT 1 FROM public.game_runtime_contracts r WHERE r.game_id = p_game_id AND r.player_id = player.id) THEN
      skipped := skipped + 1;
      CONTINUE;
    END IF;
    UPDATE public.players SET is_active = true,
      years_of_experience = COALESCE(years_of_experience, (candidate->>'exp')::SMALLINT)
    WHERE id = player.id;
    PERFORM public.enroll_simulated_free_agents(p_game_id, ARRAY[player.id]);
    enrolled := enrolled + 1;
  END LOOP;
  INSERT INTO public.free_agency_imports(game_id, snapshot, enrolled_count, skipped_count)
  VALUES (p_game_id, p_snapshot, enrolled, skipped);
  RETURN jsonb_build_object('enrolled_count', enrolled, 'skipped_count', skipped);
END;
$function$;

CREATE OR REPLACE FUNCTION public.initialize_game_schedule(p_game_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_game games%ROWTYPE;
BEGIN
  SELECT * INTO v_game FROM games WHERE id = p_game_id AND user_id = auth.uid();
  IF NOT FOUND THEN RAISE EXCEPTION 'Game not found or access denied'; END IF;
  WITH teams_ordered AS (SELECT id, row_number() OVER (ORDER BY nba_id) - 1 AS slot FROM teams),
  rounds AS (SELECT c, r, 0 AS home_slot, 1 + r % 29 AS away_slot FROM generate_series(0, 1) AS cycles(c) CROSS JOIN generate_series(0, 28) AS round_values(r)
    UNION ALL SELECT c, r, 1 + (r + k) % 29, 1 + (r - k + 29) % 29 FROM generate_series(0, 1) AS cycles(c) CROSS JOIN generate_series(0, 28) AS round_values(r) CROSS JOIN generate_series(1, 14) AS pairs(k))
  INSERT INTO scheduled_games (game_id, game_date, home_team_id, away_team_id)
  SELECT p_game_id, v_game.simulation_date + 1 + (((c * 29 + r) * (make_date(v_game.season_year + 1, 4, 15) - v_game.simulation_date - 1) / 57)::INTEGER), home.id, away.id
  FROM rounds
  JOIN teams_ordered home ON home.slot = CASE WHEN c = 0 THEN home_slot ELSE away_slot END
  JOIN teams_ordered away ON away.slot = CASE WHEN c = 0 THEN away_slot ELSE home_slot END
  ON CONFLICT DO NOTHING;
  INSERT INTO league_standings (game_id, team_id) SELECT p_game_id, id FROM teams ON CONFLICT DO NOTHING;
END;
$function$;

CREATE OR REPLACE FUNCTION public.is_available_free_agent(p_game_id uuid, p_player_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
  SELECT EXISTS (SELECT 1 FROM public.game_player_states s JOIN public.players p ON p.id = s.player_id
    WHERE s.game_id = p_game_id AND s.player_id = p_player_id
      AND s.team_id IS NULL AND s.is_active AND p.is_active)
    AND (EXISTS (SELECT 1 FROM public.free_agency_availability_enrollments e
      WHERE e.game_id = p_game_id AND e.player_id = p_player_id)
      OR EXISTS (SELECT 1 FROM public.game_roster_releases x
        WHERE x.game_id = p_game_id AND x.player_id = p_player_id))
    AND NOT EXISTS (SELECT 1 FROM public.game_active_runtime_contracts r
      WHERE r.game_id = p_game_id AND r.player_id = p_player_id)
    AND (EXISTS (SELECT 1 FROM public.game_roster_releases x
        WHERE x.game_id = p_game_id AND x.player_id = p_player_id AND x.contract_origin = 'observed')
      OR (NOT EXISTS (SELECT 1 FROM public.contracts c WHERE c.game_id = p_game_id AND c.player_id = p_player_id)
        AND NOT EXISTS (SELECT 1 FROM public.game_contract_agreements a
          WHERE a.game_id = p_game_id AND a.player_id = p_player_id)));
$function$;

CREATE OR REPLACE FUNCTION public.is_valid_game_box_score(p_result jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE STRICT
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
  SELECT CASE WHEN p_result->>'engineVersion' IN ('possessions-v1', 'possessions-v2')
    THEN public.is_valid_game_box_score_v1(jsonb_set(p_result, '{engineVersion}', '"possessions-v1"'))
    ELSE false END
$function$;

CREATE OR REPLACE FUNCTION public.is_valid_game_box_score_v1(p_result jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  row JSONB;
  field TEXT;
  side TEXT;
  elapsed INTEGER;
BEGIN
  IF p_result->>'engineVersion' IS DISTINCT FROM 'possessions-v1'
     OR jsonb_typeof(p_result->'overtimes') IS DISTINCT FROM 'number'
     OR jsonb_typeof(p_result->'homeScore') IS DISTINCT FROM 'number'
     OR jsonb_typeof(p_result->'awayScore') IS DISTINCT FROM 'number'
     OR (p_result->>'overtimes') !~ '^[0-9]+$'
     OR (p_result->>'homeScore') !~ '^[0-9]+$'
     OR (p_result->>'awayScore') !~ '^[0-9]+$'
     OR jsonb_typeof(p_result->'players') IS DISTINCT FROM 'array'
     OR NOT (p_result ?& ARRAY['overtimes','homeScore','awayScore','players']) THEN RETURN false; END IF;
  elapsed := 2880 + 300 * (p_result->>'overtimes')::INTEGER;
  IF (p_result->>'overtimes')::INTEGER NOT BETWEEN 0 AND 20
     OR (p_result->>'homeScore')::INTEGER = (p_result->>'awayScore')::INTEGER THEN RETURN false; END IF;
  FOR row IN SELECT * FROM jsonb_array_elements(p_result->'players') LOOP
    PERFORM (row->>'playerId')::UUID;
    IF nullif(row->>'playerId','') IS NULL OR nullif(row->>'playerName','') IS NULL
       OR row->>'side' IS NULL OR row->>'side' NOT IN ('home','away') THEN RETURN false; END IF;
    FOREACH field IN ARRAY ARRAY['seconds','fieldGoalsMade','fieldGoalsAttempted',
      'threePointersMade','threePointersAttempted','freeThrowsMade','freeThrowsAttempted',
      'offensiveRebounds','defensiveRebounds','assists','steals','blocks','turnovers','personalFouls','points'] LOOP
      IF NOT (row ? field) OR jsonb_typeof(row->field) IS DISTINCT FROM 'number'
        OR row->>field !~ '^[0-9]+$' THEN RETURN false; END IF;
    END LOOP;
    IF (row->>'seconds')::INTEGER > elapsed
      OR (row->>'fieldGoalsMade')::INTEGER > (row->>'fieldGoalsAttempted')::INTEGER
      OR (row->>'threePointersMade')::INTEGER > (row->>'threePointersAttempted')::INTEGER
      OR (row->>'threePointersMade')::INTEGER > (row->>'fieldGoalsMade')::INTEGER
      OR (row->>'threePointersAttempted')::INTEGER > (row->>'fieldGoalsAttempted')::INTEGER
      OR (row->>'fieldGoalsMade')::INTEGER - (row->>'threePointersMade')::INTEGER
        > (row->>'fieldGoalsAttempted')::INTEGER - (row->>'threePointersAttempted')::INTEGER
      OR (row->>'freeThrowsMade')::INTEGER > (row->>'freeThrowsAttempted')::INTEGER
      OR (row->>'points')::INTEGER <> 2*(row->>'fieldGoalsMade')::INTEGER
        + (row->>'threePointersMade')::INTEGER + (row->>'freeThrowsMade')::INTEGER THEN RETURN false; END IF;
  END LOOP;
  IF (SELECT count(DISTINCT r->>'playerId') <> count(*) FROM jsonb_array_elements(p_result->'players') r)
    THEN RETURN false; END IF;
  FOREACH side IN ARRAY ARRAY['home','away'] LOOP
    IF (SELECT count(*) NOT BETWEEN 5 AND 15 OR sum((r->>'seconds')::INTEGER) <> elapsed * 5
      OR sum((r->>'points')::INTEGER) <> (p_result->>(side || 'Score'))::INTEGER
      OR sum((r->>'assists')::INTEGER) > sum((r->>'fieldGoalsMade')::INTEGER)
      FROM jsonb_array_elements(p_result->'players') r WHERE r->>'side' = side) THEN RETURN false; END IF;
  END LOOP;
  RETURN true;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RETURN false;
END;
$function$;

CREATE OR REPLACE FUNCTION public.is_valid_player_attributes(p_attributes jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  attribute TEXT;
BEGIN
  IF jsonb_typeof(p_attributes) <> 'object' THEN RETURN false; END IF;
  IF (SELECT count(*) FROM jsonb_object_keys(p_attributes)) <> 14 THEN RETURN false; END IF;
  FOREACH attribute IN ARRAY ARRAY[
    'closeShot', 'midRangeShot', 'threePointShot', 'freeThrow', 'drawFoul', 'ballHandle',
    'passAccuracy', 'interiorDefense', 'perimeterDefense', 'steal', 'block',
    'offensiveRebound', 'defensiveRebound', 'stamina'
  ] LOOP
    IF NOT (p_attributes ? attribute)
       OR jsonb_typeof(p_attributes->attribute) <> 'number'
       OR p_attributes->>attribute !~ '^[0-9]+$' THEN RETURN false; END IF;
    IF (p_attributes->>attribute)::NUMERIC NOT BETWEEN 0 AND 99 THEN RETURN false; END IF;
  END LOOP;
  RETURN true;
END;
$function$;

CREATE OR REPLACE FUNCTION public.list_pending_free_agency_offers(p_game_id uuid)
 RETURNS SETOF free_agency_pending_offers
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT o.* FROM free_agency_pending_offers o JOIN games g ON g.id = o.game_id
  WHERE o.game_id = p_game_id AND o.owner_id = auth.uid() AND g.user_id = auth.uid()
    AND o.status = 'pending' ORDER BY o.due_date, o.created_at, o.id
$function$;

CREATE OR REPLACE FUNCTION public.materialize_game_contract_snapshots(p_game_id uuid, p_user_id uuid, p_source text, p_season text, p_version_ids uuid[], p_identity_crosswalk jsonb, p_contract_classifications jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_game games%ROWTYPE;
  v_existing UUID[];
  v_roster_count INTEGER;
  v_identity_count INTEGER;
  v_agreement_count INTEGER;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service role required'; END IF;
  SELECT * INTO v_game FROM games WHERE id = p_game_id FOR UPDATE;
  IF NOT FOUND OR v_game.user_id <> p_user_id OR v_game.status <> 'initializing'
     OR v_game.season_era_id <> 'modern' OR v_game.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'Contract materialization requires an owned initializing modern game';
  END IF;
  IF p_season <> format('%s-%s', v_game.season_year, right((v_game.season_year + 1)::TEXT, 2)) THEN
    RAISE EXCEPTION 'Contract snapshot season does not match game season';
  END IF;
  IF jsonb_typeof(p_identity_crosswalk) <> 'array' THEN RAISE EXCEPTION 'Identity crosswalk must be an array'; END IF;
  IF jsonb_typeof(p_contract_classifications) <> 'array' THEN RAISE EXCEPTION 'Contract classifications must be an array'; END IF;

  SELECT source_version_ids INTO v_existing FROM game_contract_materializations WHERE game_id = p_game_id;
  IF FOUND THEN
    IF v_existing = p_version_ids THEN
      RETURN jsonb_build_object('status', 'already-materialized', 'agreementCount',
        (SELECT count(*) FROM game_contract_agreements WHERE game_id = p_game_id));
    END IF;
    RAISE EXCEPTION 'Game was already materialized from different source versions';
  END IF;

  IF cardinality(p_version_ids) <> 30 OR cardinality(ARRAY(SELECT DISTINCT unnest(p_version_ids))) <> 30 THEN
    RAISE EXCEPTION 'Exactly 30 distinct source snapshot versions are required';
  END IF;
  IF (SELECT count(*) FROM contract_source_snapshot_versions v WHERE v.id = ANY(p_version_ids)
      AND v.source = p_source AND v.season = p_season) <> 30
     OR (SELECT count(DISTINCT v.team) FROM contract_source_snapshot_versions v WHERE v.id = ANY(p_version_ids)) <> 30 THEN
    RAISE EXCEPTION 'Source snapshot version set is incomplete or inconsistent';
  END IF;
  IF ARRAY(SELECT DISTINCT v.team FROM contract_source_snapshot_versions v
      WHERE v.id = ANY(p_version_ids) ORDER BY v.team)
     <> ARRAY['ATL','BOS','BRK','CHI','CHO','CLE','DAL','DEN','DET','GSW','HOU','IND','LAC','LAL','MEM',
       'MIA','MIL','MIN','NOP','NYK','OKC','ORL','PHI','PHO','POR','SAC','SAS','TOR','UTA','WAS'] THEN
    RAISE EXCEPTION 'Source snapshot versions do not cover the canonical 30-team set';
  END IF;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_identity_crosswalk) x
    GROUP BY x->>'sourcePlayerId' HAVING count(*) > 1)
    OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_identity_crosswalk) x
    GROUP BY x->>'targetPlayerId' HAVING count(*) > 1) THEN
    RAISE EXCEPTION 'Identity crosswalk source and target identities must be unique';
  END IF;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_identity_crosswalk) x WHERE
    x->>'matchMethod' NOT IN ('exact-provider-record', 'curated-exception')
    OR jsonb_typeof(x->'evidence') <> 'object') THEN
    RAISE EXCEPTION 'Identity crosswalk contains unvalidated records';
  END IF;

  SELECT count(*) INTO v_roster_count FROM game_player_states WHERE game_id = p_game_id;
  IF v_roster_count = 0 THEN RAISE EXCEPTION 'Modern roster must be seeded before contract materialization'; END IF;

  -- This sentinel remains the first game-owned write. The complete transaction
  -- rolls back if any copy row or coverage invariant below fails.
  INSERT INTO game_contract_materializations(game_id, source, season, source_version_ids)
  VALUES (p_game_id, p_source, p_season, p_version_ids);

  -- One materialized classification lookup and one materialized source-contract
  -- lookup feed every copy operation in this statement. In particular, seasons
  -- join the already-keyed source row before expanding only that player's salaries.
  WITH classifications AS MATERIALIZED (
    SELECT (x->>'targetPlayerId')::UUID AS target_player_id, x->'resolution' AS resolution
    FROM jsonb_array_elements(p_contract_classifications) x
  ), crosswalk AS MATERIALIZED (
    SELECT x->>'sourcePlayerId' AS source_player_id, (x->>'targetPlayerId')::UUID AS target_player_id,
      x->>'matchMethod' AS match_method, x->'evidence' AS evidence
    FROM jsonb_array_elements(p_identity_crosswalk) x
  ), source_contracts AS MATERIALIZED (
    SELECT v.id AS source_snapshot_version_id, v.observed_at, c.contract,
      c.contract->>'playerSlug' AS source_player_id
    FROM contract_source_snapshot_versions v
    CROSS JOIN LATERAL jsonb_array_elements(v.payload->'contracts') c(contract)
    WHERE v.id = ANY(p_version_ids)
  ), matched AS MATERIALIZED (
    SELECT gps.player_id, gps.team_id, sc.source_snapshot_version_id, sc.observed_at, sc.contract,
      sc.source_player_id, cw.match_method, cw.evidence
    FROM source_contracts sc
    JOIN crosswalk cw ON cw.source_player_id = sc.source_player_id
    JOIN game_player_states gps ON gps.game_id = p_game_id AND gps.player_id = cw.target_player_id
    JOIN teams t ON t.id = gps.team_id AND t.abbreviation = (cw.evidence->>'nbaTeam')
    WHERE sc.contract->>'teamAbbreviation' = (cw.evidence->>'sourceTeam')
  ), inserted_identities AS (
    INSERT INTO game_contract_identities(game_id, player_id, team_id, resolution_status, contract_type,
      provenance_quality, source_method, estimated, cap_treatment, exclusion_evidence, source_player_id,
      source_snapshot_version_id, match_method, match_evidence)
    SELECT p_game_id, gps.player_id, gps.team_id,
      CASE
        WHEN c.resolution->>'status' = 'excluded' THEN 'inactive-excluded'
        WHEN c.resolution->>'contractType' = 'two-way' THEN 'official-two-way'
        WHEN (c.resolution->>'estimated')::BOOLEAN THEN 'estimated-minimum'
        WHEN c.resolution->>'status' = 'resolved' THEN 'observed-standard'
        ELSE 'unclassified'
      END,
      c.resolution->>'contractType', c.resolution->>'quality', c.resolution->>'method',
      COALESCE((c.resolution->>'estimated')::BOOLEAN, false), c.resolution->>'capTreatment',
      c.resolution->'evidence', m.source_player_id, m.source_snapshot_version_id, m.match_method, m.evidence
    FROM game_player_states gps
    LEFT JOIN matched m ON m.player_id = gps.player_id
    LEFT JOIN classifications c ON c.target_player_id = gps.player_id
    WHERE gps.game_id = p_game_id
  ), inserted_observed_agreements AS (
    INSERT INTO game_contract_agreements(game_id, player_id, team_id, start_season_label,
      end_season_label, remaining_guaranteed_amount, contract_type, provenance_quality, source_method,
      estimated, cap_treatment)
    SELECT p_game_id, m.player_id, m.team_id, NULL, NULL,
      NULLIF(m.contract->>'remainingGuaranteedAmount', '')::BIGINT, 'standard',
      c.resolution->>'quality', c.resolution->>'method', false, 'standard-cap-and-matching'
    FROM matched m
    JOIN classifications c ON c.target_player_id = m.player_id
    WHERE c.resolution->>'contractType' = 'standard'
      AND COALESCE((c.resolution->>'estimated')::BOOLEAN, false) = false
    RETURNING id, player_id
  ), inserted_estimated_agreements AS (
    INSERT INTO game_contract_agreements(game_id, player_id, team_id, start_season_label,
      end_season_label, remaining_guaranteed_amount, contract_type, provenance_quality, source_method,
      estimated, cap_treatment)
    SELECT p_game_id, gps.player_id, gps.team_id, p_season, p_season, NULL, 'standard', 'estimated',
      c.resolution->>'method', true, 'standard-cap-and-matching'
    FROM game_player_states gps
    JOIN classifications c ON c.target_player_id = gps.player_id
    WHERE gps.game_id = p_game_id
      AND c.resolution->>'status' = 'resolved'
      AND c.resolution->>'contractType' = 'standard'
      AND (c.resolution->>'estimated')::BOOLEAN = true
    RETURNING id, player_id
  ), inserted_provenance AS (
    INSERT INTO game_contract_provenance(agreement_id, game_id, source, source_url, source_player_id,
      source_snapshot_version_id, observed_at, notes)
    SELECT i.id, p_game_id, p_source, m.contract->>'playerUrl', m.source_player_id,
      m.source_snapshot_version_id, m.observed_at, m.contract->'contractNotes'
    FROM inserted_observed_agreements i
    JOIN matched m ON m.player_id = i.player_id
  ), inserted_estimated_seasons AS (
    INSERT INTO game_contract_seasons(agreement_id, game_id, season_label, start_year, end_year,
      salary_amount, option_kind, guarantee_kind)
    SELECT a.id, p_game_id, p_season, v_game.season_year, v_game.season_year + 1,
      (c.resolution->>'salaryAmount')::BIGINT, 'none', 'unknown'
    FROM inserted_estimated_agreements a
    JOIN classifications c ON c.target_player_id = a.player_id
    RETURNING agreement_id
  )
  INSERT INTO game_contract_seasons(agreement_id, game_id, season_label, start_year, end_year,
    salary_amount, option_kind, guarantee_kind)
  SELECT a.id, p_game_id, s.value->>'season', split_part(s.value->>'season', '-', 1)::INTEGER,
    split_part(s.value->>'season', '-', 1)::INTEGER + 1,
    NULLIF(s.value->>'amount', '')::BIGINT, s.value->>'optionKind', 'unknown'
  FROM inserted_observed_agreements a
  JOIN matched m ON m.player_id = a.player_id
  JOIN source_contracts sc
    ON sc.source_snapshot_version_id = m.source_snapshot_version_id
   AND sc.source_player_id = m.source_player_id
  CROSS JOIN LATERAL jsonb_array_elements(sc.contract->'salaries') s(value);

  SELECT count(*) INTO v_identity_count FROM game_contract_identities WHERE game_id = p_game_id;
  SELECT count(*) INTO v_agreement_count FROM game_contract_agreements WHERE game_id = p_game_id;
  IF v_identity_count <> v_roster_count THEN RAISE EXCEPTION 'Every roster identity must be classified'; END IF;
  IF EXISTS (SELECT 1 FROM game_contract_identities WHERE game_id = p_game_id AND resolution_status = 'unclassified') OR EXISTS (
    SELECT 1 FROM game_contract_agreements a LEFT JOIN game_contract_seasons s
      ON s.agreement_id = a.id AND s.start_year = v_game.season_year
    WHERE a.game_id = p_game_id AND s.salary_amount IS NULL
  ) THEN RAISE EXCEPTION 'Contract coverage is insufficient; game activation is blocked'; END IF;
  RETURN jsonb_build_object('status', 'materialized', 'rosterCount', v_roster_count,
    'agreementCount', v_agreement_count, 'unmatchedCount', v_roster_count - v_agreement_count);
END;
$function$;

CREATE OR REPLACE FUNCTION public.materialize_game_player_attributes(p_game_id uuid, p_owner_id uuid, p_season_year integer, p_source_version_id uuid, p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_game public.games%ROWTYPE;
  v_source public.player_rating_source_versions%ROWTYPE;
  v_header public.game_attribute_materializations%ROWTYPE;
  v_row JSONB;
  v_source_player JSONB;
  v_player_id UUID;
  v_origin TEXT;
  v_match_method TEXT;
  v_source_slug TEXT;
  v_source_overall SMALLINT;
  v_generator_version TEXT;
  v_expected_count INTEGER;
  v_count INTEGER;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Service role required';
  END IF;
  IF p_game_id IS NULL OR p_owner_id IS NULL OR p_source_version_id IS NULL
     OR p_season_year IS NULL OR p_rows IS NULL OR jsonb_typeof(p_rows) IS DISTINCT FROM 'array'
     OR jsonb_array_length(p_rows) NOT BETWEEN 1 AND 10000 THEN
    RAISE EXCEPTION 'Invalid player attribute materialization input';
  END IF;

  SELECT * INTO v_game FROM public.games
    WHERE id = p_game_id AND user_id = p_owner_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND OR v_game.status <> 'initializing' OR v_game.season_era_id <> 'modern'
     OR v_game.season_year <> p_season_year THEN
    RAISE EXCEPTION 'Owned initializing modern game required';
  END IF;
  SELECT * INTO v_source FROM public.player_rating_source_versions
    WHERE id = p_source_version_id;
  IF NOT FOUND OR v_source.game_version <> '2K27'
     OR jsonb_typeof(v_source.payload->'players') IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'Validated current player rating source required';
  END IF;
  SELECT count(*)::INTEGER INTO v_expected_count FROM public.game_player_states
    WHERE game_id = p_game_id;
  IF v_expected_count <> jsonb_array_length(p_rows) THEN
    RAISE EXCEPTION 'Player attribute coverage does not match game roster';
  END IF;

  SELECT * INTO v_header FROM public.game_attribute_materializations
    WHERE game_id = p_game_id AND season_year = p_season_year FOR UPDATE;
  IF FOUND THEN
    IF v_header.source_version_id <> p_source_version_id
       OR v_header.player_count <> v_expected_count
       OR (SELECT count(DISTINCT input."playerId")
         FROM jsonb_to_recordset(p_rows) AS input("playerId" UUID)) <> v_expected_count THEN
      RAISE EXCEPTION 'Attribute materialization retry changed its source or coverage';
    END IF;
    IF EXISTS (
      SELECT 1
      FROM jsonb_to_recordset(p_rows) AS input(
        "playerId" UUID, origin TEXT, "matchMethod" TEXT, attributes JSONB,
        "sourceSlug" TEXT, "sourceOverall" SMALLINT, "generatorVersion" TEXT,
        "identityEvidence" JSONB
      )
      LEFT JOIN public.game_player_attributes existing
        ON existing.game_id = p_game_id AND existing.season_year = p_season_year
       AND existing.player_id = input."playerId"
      WHERE existing.player_id IS NULL
         OR existing.origin IS DISTINCT FROM input.origin
         OR existing.match_method IS DISTINCT FROM input."matchMethod"
         OR existing.attributes IS DISTINCT FROM input.attributes
         OR existing.source_slug IS DISTINCT FROM input."sourceSlug"
         OR existing.source_overall IS DISTINCT FROM input."sourceOverall"
         OR existing.generator_version IS DISTINCT FROM input."generatorVersion"
         OR existing.identity_evidence IS DISTINCT FROM input."identityEvidence"
    ) OR (
      SELECT count(*) FROM public.game_player_attributes
      WHERE game_id = p_game_id AND season_year = p_season_year
    ) <> v_expected_count THEN
      RAISE EXCEPTION 'Attribute materialization retry changed its payload';
    END IF;
    RETURN jsonb_build_object('status', 'already-materialized', 'playerCount', v_expected_count,
      'sourceVersionId', p_source_version_id);
  END IF;

  FOR v_row IN SELECT value FROM jsonb_array_elements(p_rows) LOOP
    v_player_id := NULLIF(v_row->>'playerId', '')::UUID;
    v_origin := v_row->>'origin';
    v_match_method := v_row->>'matchMethod';
    v_source_slug := NULLIF(v_row->>'sourceSlug', '');
    v_source_overall := NULLIF(v_row->>'sourceOverall', '')::SMALLINT;
    v_generator_version := NULLIF(v_row->>'generatorVersion', '');
    IF v_player_id IS NULL OR v_origin IS NULL OR v_match_method IS NULL
       OR jsonb_typeof(v_row->'attributes') IS DISTINCT FROM 'object'
       OR jsonb_typeof(v_row->'identityEvidence') IS DISTINCT FROM 'object'
       OR NOT public.is_valid_player_attributes(v_row->'attributes') THEN
      RAISE EXCEPTION 'Invalid player attribute row';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.game_player_states
      WHERE game_id = p_game_id AND player_id = v_player_id) THEN
      RAISE EXCEPTION 'Player does not belong to game roster';
    END IF;
    IF v_origin = 'nba2kapi' THEN
      IF v_source_slug IS NULL OR v_source_overall IS NULL OR v_generator_version IS NOT NULL
         OR v_match_method NOT IN ('name-and-team', 'name-and-height', 'reviewed-espn-alias') THEN
        RAISE EXCEPTION 'Invalid imported player attribute provenance';
      END IF;
      SELECT value INTO v_source_player FROM jsonb_array_elements(v_source.payload->'players')
        WHERE value->>'slug' = v_source_slug;
      IF v_source_player IS NULL
         OR (v_source_player->'attributes') IS DISTINCT FROM v_row->'attributes'
         OR (v_source_player->>'overall')::SMALLINT IS DISTINCT FROM v_source_overall THEN
        RAISE EXCEPTION 'Imported player attributes do not match source version';
      END IF;
    ELSIF v_origin = 'estimated' THEN
      IF v_source_slug IS NOT NULL OR v_source_overall IS NOT NULL
         OR v_generator_version IS DISTINCT FROM 'replacement-v1'
         OR v_match_method NOT IN ('missing-source', 'incomplete-attributes',
           'ambiguous-identity', 'uncorroborated-identity') THEN
        RAISE EXCEPTION 'Invalid estimated player attribute provenance';
      END IF;
    ELSE
      RAISE EXCEPTION 'Unknown player attribute origin';
    END IF;
  END LOOP;

  INSERT INTO public.game_attribute_materializations(
    game_id, season_year, source_version_id, player_count
  ) VALUES (p_game_id, p_season_year, p_source_version_id, v_expected_count);
  INSERT INTO public.game_player_attributes(
    game_id, season_year, player_id, origin, match_method, attributes,
    source_slug, source_overall, generator_version, identity_evidence
  )
  SELECT p_game_id, p_season_year, input."playerId", input.origin, input."matchMethod",
    input.attributes, NULLIF(input."sourceSlug", ''), input."sourceOverall",
    NULLIF(input."generatorVersion", ''), input."identityEvidence"
  FROM jsonb_to_recordset(p_rows) AS input(
    "playerId" UUID, origin TEXT, "matchMethod" TEXT, attributes JSONB,
    "sourceSlug" TEXT, "sourceOverall" SMALLINT, "generatorVersion" TEXT,
    "identityEvidence" JSONB
  );
  GET DIAGNOSTICS v_count = ROW_COUNT;
  IF v_count <> v_expected_count THEN
    RAISE EXCEPTION 'Player attribute materialization inserted incomplete coverage';
  END IF;
  RETURN jsonb_build_object('status', 'materialized', 'playerCount', v_count,
    'sourceVersionId', p_source_version_id);
END;
$function$;

CREATE OR REPLACE FUNCTION public.offseason_contract_evidence(p_game_id uuid, p_season_year integer)
 RETURNS TABLE(player_id uuid, team_id uuid, classification text, next_salary bigint, evidence jsonb)
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
WITH source AS (
  SELECT s.player_id,s.team_id,to_jsonb(r) runtime,to_jsonb(i) identity,
    to_jsonb(a) agreement,to_jsonb(c) legacy,
    (SELECT coalesce(jsonb_agg(to_jsonb(cs) ORDER BY cs.start_year,cs.id),'[]')
      FROM public.game_contract_seasons cs WHERE cs.agreement_id=a.id) seasons,
    n.option_kind,n.salary_amount,n.matches
  FROM public.games g JOIN public.game_player_states s ON s.game_id=g.id AND s.team_id=g.selected_team_id
  LEFT JOIN public.game_active_runtime_contracts r ON r.game_id=g.id AND r.player_id=s.player_id
  LEFT JOIN public.game_contract_identities i ON i.game_id=g.id AND i.player_id=s.player_id
  LEFT JOIN public.game_contract_agreements a ON a.game_id=g.id AND a.player_id=s.player_id
  LEFT JOIN public.contracts c ON c.game_id=g.id AND c.player_id=s.player_id
  LEFT JOIN LATERAL (SELECT min(cs.option_kind) option_kind,min(cs.salary_amount) salary_amount,count(*) matches
    FROM public.game_contract_seasons cs WHERE cs.agreement_id=a.id AND cs.start_year=p_season_year+1
      AND (cs.salary_amount IS NOT NULL OR cs.option_kind IN ('player','team'))) n ON true
  WHERE g.id=p_game_id
), terms AS (
 SELECT *,coalesce(runtime,CASE WHEN identity IS NULL AND agreement IS NULL THEN legacy END) term
 FROM source
), classified AS (
 SELECT *,CASE
 WHEN runtime IS NULL AND (identity IS NOT NULL OR agreement IS NOT NULL) THEN CASE
   WHEN identity IS NULL OR agreement IS NULL OR (identity->>'estimated')::BOOLEAN
     OR identity->>'resolution_status' NOT IN ('observed-standard','official-two-way')
     OR identity->>'provenance_quality'='estimated' OR agreement->>'provenance_quality'='estimated'
     OR (agreement->>'estimated')::BOOLEAN OR matches>1 THEN NULL
   WHEN left(agreement->>'end_season_label',4)::INTEGER<p_season_year
     OR (left(agreement->>'end_season_label',4)::INTEGER=p_season_year AND matches>0) THEN NULL
   WHEN matches=0 AND left(agreement->>'end_season_label',4)::INTEGER=p_season_year THEN 'expiring'
   WHEN option_kind='team' THEN 'team_option'
   WHEN option_kind='player' THEN 'player_option' END
 ELSE CASE
   WHEN term IS NULL OR (term->>'start_year')::INTEGER>p_season_year
     OR (runtime IS NULL AND legacy->>'team_id' IS DISTINCT FROM team_id::TEXT)
     OR (term->>'end_year')::INTEGER<p_season_year
     OR ((term->>'is_team_option')::BOOLEAN AND (term->>'is_player_option')::BOOLEAN) THEN NULL
   WHEN (term->>'end_year')::INTEGER=p_season_year THEN 'expiring'
   WHEN (term->>'end_year')::INTEGER=p_season_year+1 THEN CASE
     WHEN (term->>'is_team_option')::BOOLEAN THEN 'team_option'
     WHEN (term->>'is_player_option')::BOOLEAN THEN 'player_option' END END END kind
 FROM terms
)
SELECT player_id,team_id,kind,
 CASE WHEN kind='expiring' THEN NULL WHEN runtime IS NOT NULL THEN (runtime->>'annual_salary')::BIGINT
 WHEN identity IS NOT NULL OR agreement IS NOT NULL THEN salary_amount
 ELSE (legacy->>('salary_y'||(p_season_year+2-(legacy->>'start_year')::INTEGER)))::BIGINT END,
 jsonb_build_object('runtime',runtime,'identity',identity,'agreement',agreement,'legacy',legacy,'seasons',seasons)
FROM classified WHERE kind IS NOT NULL;
$function$;

CREATE OR REPLACE FUNCTION public.possession_random(p_seed text, p_draw integer)
 RETURNS double precision
 LANGUAGE sql
 IMMUTABLE STRICT
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
  SELECT ('x' || substr(md5(p_seed || ':' || p_draw::TEXT), 1, 8))::bit(32)::bigint / 4294967296.0
$function$;

CREATE OR REPLACE FUNCTION public.prepare_offseason_contracts(p_game_id uuid, p_season_year integer)
 RETURNS SETOF game_offseason_contracts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE g public.games%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT * INTO g FROM public.games WHERE id=p_game_id AND user_id=auth.uid()
    AND status='active' AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Game not found or access denied'; END IF;
  IF p_season_year IS NULL OR g.season_year IS DISTINCT FROM p_season_year THEN RAISE EXCEPTION 'Season year does not match the current season'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.game_offseasons WHERE game_id=g.id AND season_year=p_season_year) THEN RAISE EXCEPTION 'Offseason entry required'; END IF;
  IF EXISTS (SELECT 1 FROM public.game_offseason_contracts l
    LEFT JOIN public.offseason_contract_evidence(g.id,p_season_year) e USING(player_id)
    WHERE l.game_id=g.id AND l.season_year=p_season_year
      AND (e.player_id IS NULL OR l.team_id IS DISTINCT FROM e.team_id OR l.evidence IS DISTINCT FROM e.evidence)) THEN
    RAISE EXCEPTION 'Offseason contract evidence changed';
  END IF;
  INSERT INTO public.game_offseason_contracts(game_id,season_year,player_id,team_id,classification,next_salary,evidence)
    SELECT g.id,p_season_year,e.* FROM public.offseason_contract_evidence(g.id,p_season_year) e
    ON CONFLICT (game_id,season_year,player_id) DO NOTHING;
  RETURN QUERY SELECT * FROM public.game_offseason_contracts WHERE game_id=g.id AND season_year=p_season_year ORDER BY player_id;
END $function$;

CREATE OR REPLACE FUNCTION public.prepare_play_in(p_game_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE g public.games%ROWTYPE; conf TEXT; pairing INTEGER; home_id UUID; away_id UUID;
  fixture_id UUID; first_game public.scheduled_games%ROWTYPE; second_game public.scheduled_games%ROWTYPE;
  last_game public.scheduled_games%ROWTYPE;
BEGIN
  SELECT * INTO STRICT g FROM public.games WHERE id = p_game_id FOR UPDATE;
  IF (SELECT count(*) FROM public.postseason_qualifications q
    WHERE q.game_id = g.id AND q.season_year = g.season_year) <> 30
  THEN RAISE EXCEPTION 'Frozen regular-season qualification required'; END IF;
  INSERT INTO public.postseason_playoff_seeds(game_id, season_year, team_id, conference, seed)
    SELECT q.game_id, q.season_year, q.team_id, q.conference, q.seed
    FROM public.postseason_qualifications q WHERE q.game_id = g.id AND q.season_year = g.season_year AND q.seed <= 6
    ON CONFLICT DO NOTHING;
  FOREACH conf IN ARRAY ARRAY['East', 'West'] LOOP
    FOREACH pairing IN ARRAY ARRAY[7, 9] LOOP
      IF NOT EXISTS (SELECT 1 FROM public.postseason_play_in_games p WHERE p.game_id = g.id
        AND p.season_year = g.season_year AND p.conference = conf
        AND p.stage = CASE WHEN pairing = 7 THEN 'seven_eight' ELSE 'nine_ten' END) THEN
        SELECT q.team_id INTO STRICT home_id FROM public.postseason_qualifications q
          WHERE q.game_id = g.id AND q.season_year = g.season_year AND q.conference = conf AND q.seed = pairing;
        SELECT q.team_id INTO STRICT away_id FROM public.postseason_qualifications q
          WHERE q.game_id = g.id AND q.season_year = g.season_year AND q.conference = conf AND q.seed = pairing + 1;
        INSERT INTO public.scheduled_games(game_id, season_year, competition_phase, game_date, home_team_id, away_team_id)
          VALUES (g.id, g.season_year, 'play_in', g.simulation_date + 2, home_id, away_id) RETURNING id INTO fixture_id;
        INSERT INTO public.postseason_play_in_games VALUES (g.id, g.season_year, conf,
          CASE WHEN pairing = 7 THEN 'seven_eight' ELSE 'nine_ten' END, fixture_id);
      END IF;
    END LOOP;
    SELECT f.* INTO STRICT first_game FROM public.scheduled_games f JOIN public.postseason_play_in_games p
      ON p.scheduled_game_id = f.id WHERE p.game_id = g.id AND p.season_year = g.season_year
        AND p.conference = conf AND p.stage = 'seven_eight';
    SELECT f.* INTO STRICT second_game FROM public.scheduled_games f JOIN public.postseason_play_in_games p
      ON p.scheduled_game_id = f.id WHERE p.game_id = g.id AND p.season_year = g.season_year
        AND p.conference = conf AND p.stage = 'nine_ten';
    IF first_game.status <> 'completed' OR second_game.status <> 'completed' THEN CONTINUE; END IF;
    INSERT INTO public.postseason_playoff_seeds VALUES (g.id, g.season_year, first_game.winner_team_id, conf, 7)
      ON CONFLICT DO NOTHING;
    IF NOT EXISTS (SELECT 1 FROM public.postseason_play_in_games p WHERE p.game_id = g.id
      AND p.season_year = g.season_year AND p.conference = conf AND p.stage = 'eighth_seed') THEN
      home_id := CASE WHEN first_game.winner_team_id = first_game.home_team_id
        THEN first_game.away_team_id ELSE first_game.home_team_id END;
      INSERT INTO public.scheduled_games(game_id, season_year, competition_phase, game_date, home_team_id, away_team_id)
        VALUES (g.id, g.season_year, 'play_in', greatest(first_game.game_date, second_game.game_date) + 2,
          home_id, second_game.winner_team_id) RETURNING id INTO fixture_id;
      INSERT INTO public.postseason_play_in_games VALUES (g.id, g.season_year, conf, 'eighth_seed', fixture_id);
    END IF;
    SELECT f.* INTO STRICT last_game FROM public.scheduled_games f JOIN public.postseason_play_in_games p
      ON p.scheduled_game_id = f.id WHERE p.game_id = g.id AND p.season_year = g.season_year
        AND p.conference = conf AND p.stage = 'eighth_seed';
    IF last_game.status = 'completed' THEN
      INSERT INTO public.postseason_playoff_seeds VALUES (g.id, g.season_year, last_game.winner_team_id, conf, 8)
        ON CONFLICT DO NOTHING;
    END IF;
  END LOOP;
END;
$function$;

CREATE OR REPLACE FUNCTION public.prepare_playoffs(p_game_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE g public.games%ROWTYPE; s public.postseason_series%ROWTYPE;
  r INTEGER; conf TEXT; slot INTEGER; home_id UUID; away_id UUID; candidate UUID[];
  seed_a INTEGER; seed_b INTEGER; hw INTEGER; aw INTEGER; n INTEGER;
  fixture_id UUID; last_date DATE; round_end DATE;
BEGIN
  SELECT * INTO STRICT g FROM public.games WHERE id = p_game_id FOR UPDATE;
  IF (SELECT count(*) FROM public.postseason_playoff_seeds p
    WHERE p.game_id = g.id AND p.season_year = g.season_year) <> 16 THEN RETURN; END IF;

  FOR s IN SELECT * FROM public.postseason_series p
    WHERE p.game_id = g.id AND p.season_year = g.season_year AND p.winner_team_id IS NULL
  LOOP
    SELECT count(*) FILTER (WHERE f.winner_team_id = s.home_team_id),
      count(*) FILTER (WHERE f.winner_team_id = s.away_team_id) INTO hw, aw
      FROM public.postseason_series_games link JOIN public.scheduled_games f ON f.id = link.scheduled_game_id
      WHERE link.series_id = s.id AND f.status = 'completed';
    UPDATE public.postseason_series SET home_wins = hw, away_wins = aw,
      winner_team_id = CASE WHEN hw = 4 THEN s.home_team_id WHEN aw = 4 THEN s.away_team_id END
      WHERE id = s.id;
  END LOOP;

  FOR r IN 1..4 LOOP
    IF r > 1 AND (SELECT count(*) FROM public.postseason_series p WHERE p.game_id = g.id
      AND p.season_year = g.season_year AND p.round = r - 1 AND p.winner_team_id IS NOT NULL)
      <> power(2, 5 - r) THEN EXIT; END IF;
    FOREACH conf IN ARRAY CASE WHEN r = 4 THEN ARRAY['Finals'] ELSE ARRAY['East', 'West'] END LOOP
      FOR slot IN 1..CASE WHEN r = 4 THEN 1 ELSE power(2, 3 - r)::INTEGER END LOOP
        IF EXISTS (SELECT 1 FROM public.postseason_series p WHERE p.game_id = g.id
          AND p.season_year = g.season_year AND p.round = r AND p.conference = conf AND p.bracket_slot = slot)
          THEN CONTINUE; END IF;
        IF r = 1 THEN
          seed_a := (ARRAY[1,4,2,3])[slot]; seed_b := 9 - seed_a;
          SELECT p.team_id INTO STRICT home_id FROM public.postseason_playoff_seeds p
            WHERE p.game_id = g.id AND p.season_year = g.season_year AND p.conference = conf AND p.seed = seed_a;
          SELECT p.team_id INTO STRICT away_id FROM public.postseason_playoff_seeds p
            WHERE p.game_id = g.id AND p.season_year = g.season_year AND p.conference = conf AND p.seed = seed_b;
        ELSE
          SELECT array_agg(p.winner_team_id ORDER BY p.conference, p.bracket_slot) INTO candidate
            FROM public.postseason_series p WHERE p.game_id = g.id AND p.season_year = g.season_year
            AND p.round = r - 1 AND (r = 4 OR (p.conference = conf AND p.bracket_slot IN (slot * 2 - 1, slot * 2)));
          IF r < 4 THEN
            SELECT array_agg(p.team_id ORDER BY p.seed) INTO candidate FROM public.postseason_playoff_seeds p
              WHERE p.game_id = g.id AND p.season_year = g.season_year AND p.team_id = ANY(candidate);
          ELSE
            -- Finals use regular-season record, head-to-head, differential, then frozen lottery order.
            SELECT array_agg(q.team_id ORDER BY
              coalesce(q.wins::NUMERIC / nullif(q.wins + q.losses, 0), 0) DESC,
              (SELECT count(*) FROM public.scheduled_games f WHERE f.game_id = g.id AND f.season_year = g.season_year
                AND f.competition_phase = 'regular_season' AND f.status = 'completed' AND f.winner_team_id = q.team_id
                AND f.home_team_id = ANY(candidate) AND f.away_team_id = ANY(candidate)) DESC,
              (SELECT coalesce(sum(CASE WHEN f.home_team_id = q.team_id THEN f.home_score - f.away_score
                ELSE f.away_score - f.home_score END), 0) FROM public.scheduled_games f
                WHERE f.game_id = g.id AND f.season_year = g.season_year AND f.competition_phase = 'regular_season'
                AND f.status = 'completed' AND q.team_id IN (f.home_team_id, f.away_team_id)) DESC,
              q.draw_order) INTO candidate FROM public.postseason_qualifications q
              WHERE q.game_id = g.id AND q.season_year = g.season_year AND q.team_id = ANY(candidate);
          END IF;
          home_id := candidate[1]; away_id := candidate[2];
        END IF;
        INSERT INTO public.postseason_series(game_id, season_year, round, conference, bracket_slot, home_team_id, away_team_id)
          VALUES (g.id, g.season_year, r, conf, slot, home_id, away_id);
      END LOOP;
    END LOOP;
  END LOOP;

  FOR s IN SELECT * FROM public.postseason_series p WHERE p.game_id = g.id
    AND p.season_year = g.season_year AND p.winner_team_id IS NULL
  LOOP
    IF EXISTS (SELECT 1 FROM public.postseason_series_games link JOIN public.scheduled_games f
      ON f.id = link.scheduled_game_id WHERE link.series_id = s.id AND f.status = 'scheduled') THEN CONTINUE; END IF;
    SELECT count(*) + 1, max(f.game_date) INTO n, last_date FROM public.postseason_series_games link
      JOIN public.scheduled_games f ON f.id = link.scheduled_game_id WHERE link.series_id = s.id;
    IF n = 1 THEN
      SELECT max(f.game_date) INTO round_end FROM public.scheduled_games f WHERE f.game_id = g.id
        AND f.season_year = g.season_year AND (CASE WHEN s.round = 1 THEN f.competition_phase = 'play_in'
          ELSE EXISTS (SELECT 1 FROM public.postseason_series_games link JOIN public.postseason_series prev
            ON prev.id = link.series_id WHERE link.scheduled_game_id = f.id AND prev.round = s.round - 1) END);
      last_date := greatest(g.simulation_date, round_end);
    END IF;
    home_id := CASE WHEN n IN (1,2,5,7) THEN s.home_team_id ELSE s.away_team_id END;
    away_id := CASE WHEN n IN (1,2,5,7) THEN s.away_team_id ELSE s.home_team_id END;
    INSERT INTO public.scheduled_games(game_id, season_year, competition_phase, game_date, home_team_id, away_team_id)
      VALUES (g.id, g.season_year, 'playoffs', last_date + 2, home_id, away_id) RETURNING id INTO fixture_id;
    INSERT INTO public.postseason_series_games VALUES (g.id, s.id, n, fixture_id);
  END LOOP;

  INSERT INTO public.postseason_results(game_id, season_year, finals_series_id, champion_team_id, runner_up_team_id, completed_on)
    SELECT g.id, g.season_year, p.id, p.winner_team_id,
      CASE WHEN p.winner_team_id = p.home_team_id THEN p.away_team_id ELSE p.home_team_id END, g.simulation_date
    FROM public.postseason_series p WHERE p.game_id = g.id AND p.season_year = g.season_year
      AND p.round = 4 AND p.winner_team_id IS NOT NULL ON CONFLICT DO NOTHING;
END;
$function$;

CREATE OR REPLACE FUNCTION public.promote_current_roster(p_run_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_expected_team_count INTEGER; v_staged_team_count INTEGER;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('current-roster', 0));
  SELECT expected_team_count INTO v_expected_team_count FROM roster_refresh_runs
    WHERE id = p_run_id AND status = 'pending' FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Roster refresh run is missing or not pending'; END IF;
  SELECT count(DISTINCT team_id) INTO v_staged_team_count FROM roster_refresh_staging WHERE run_id = p_run_id;
  IF v_staged_team_count <> v_expected_team_count
    OR EXISTS (SELECT 1 FROM teams t WHERE NOT EXISTS
      (SELECT 1 FROM roster_refresh_staging s WHERE s.run_id = p_run_id AND s.team_id = t.id))
    OR EXISTS (SELECT 1 FROM roster_refresh_staging s WHERE s.run_id = p_run_id
      AND NOT EXISTS (SELECT 1 FROM teams t WHERE t.id = s.team_id))
  THEN RAISE EXCEPTION 'Roster refresh run does not contain the complete team set'; END IF;
  UPDATE players p SET espn_id = s.player_source_id, updated_at = now()
    FROM roster_refresh_staging s WHERE s.run_id = p_run_id AND s.provider = 'espn'
    AND p.espn_id IS NULL AND lower(p.full_name) = lower(s.payload->>'full_name');
  INSERT INTO players (espn_id, team_id, first_name, last_name, full_name, position,
    height, weight, jersey_number, years_of_experience, age, birth_date, is_active)
  SELECT s.player_source_id, s.team_id, s.payload->>'first_name', s.payload->>'last_name',
    s.payload->>'full_name', s.payload->>'position', s.payload->>'height', s.payload->>'weight',
    s.payload->>'jersey_number', NULLIF(s.payload->>'years_of_experience', '')::SMALLINT,
    NULLIF(s.payload->>'age', '')::SMALLINT, NULLIF(s.payload->>'birth_date', '')::DATE, true
  FROM roster_refresh_staging s WHERE s.run_id = p_run_id AND s.provider = 'espn'
    AND NOT EXISTS (SELECT 1 FROM players p WHERE p.espn_id = s.player_source_id);
  UPDATE players SET team_id = NULL, is_active = false, updated_at = now() WHERE team_id IS NOT NULL;
  UPDATE players p SET team_id = s.team_id, is_active = true, updated_at = now(),
    first_name = s.payload->>'first_name', last_name = s.payload->>'last_name',
    full_name = s.payload->>'full_name', position = s.payload->>'position',
    height = s.payload->>'height', weight = s.payload->>'weight',
    jersey_number = s.payload->>'jersey_number',
    years_of_experience = NULLIF(s.payload->>'years_of_experience', '')::SMALLINT,
    age = COALESCE(NULLIF(s.payload->>'age', '')::SMALLINT, p.age),
    birth_date = COALESCE(NULLIF(s.payload->>'birth_date', '')::DATE, p.birth_date)
  FROM roster_refresh_staging s WHERE s.run_id = p_run_id AND s.provider = 'espn'
    AND p.espn_id = s.player_source_id;
  UPDATE roster_refresh_runs SET status = 'success', completed_team_count = v_staged_team_count,
    updated_at = now() WHERE id = p_run_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.publish_player_rating_snapshot(p_game_version text, p_lease_id uuid, p_snapshot jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  head public.player_rating_source_cache%ROWTYPE;
  version_uuid UUID;
  hash TEXT := p_snapshot->>'contentHash';
  v_now TIMESTAMPTZ;
  snapshot JSONB;
BEGIN
  IF p_snapshot IS NULL OR jsonb_typeof(p_snapshot) <> 'object'
     OR p_snapshot->>'source' IS DISTINCT FROM 'nba2kapi'
     OR p_snapshot->>'sourceUrl' IS DISTINCT FROM 'https://api.nba2kapi.com/api/players/bulk?teamType=curr'
     OR p_snapshot->>'gameVersion' IS DISTINCT FROM p_game_version
     OR hash IS NULL OR hash !~ '^[a-f0-9]{64}$'
     OR jsonb_typeof(p_snapshot->'players') IS DISTINCT FROM 'array'
     OR jsonb_typeof(p_snapshot->'excludedPlayers') IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'Invalid player rating snapshot';
  END IF;
  IF jsonb_array_length(p_snapshot->'players') = 0
     OR jsonb_array_length(p_snapshot->'players') + jsonb_array_length(p_snapshot->'excludedPlayers') > 10000 THEN
    RAISE EXCEPTION 'Invalid player rating snapshot size';
  END IF;
  SELECT * INTO head FROM public.player_rating_source_cache
    WHERE game_version = p_game_version FOR UPDATE;
  v_now := clock_timestamp();
  IF NOT FOUND OR p_lease_id IS NULL OR head.lease_id IS DISTINCT FROM p_lease_id
     OR head.lease_expires_at <= v_now THEN
    RAISE EXCEPTION 'Player rating refresh lease lost';
  END IF;
  INSERT INTO public.player_rating_source_versions(game_version, content_hash, payload)
    VALUES (p_game_version, hash, p_snapshot)
    ON CONFLICT (game_version, content_hash) DO NOTHING RETURNING id INTO version_uuid;
  IF version_uuid IS NULL THEN
    SELECT id INTO version_uuid FROM public.player_rating_source_versions
      WHERE game_version = p_game_version AND content_hash = hash;
  END IF;
  UPDATE public.player_rating_source_cache SET version_id = version_uuid,
    revalidated_at = v_now, next_refresh_at = v_now + interval '24 hours',
    lease_id = NULL, lease_expires_at = NULL WHERE game_version = p_game_version;
  SELECT payload INTO snapshot FROM public.player_rating_source_versions WHERE id = version_uuid;
  RETURN jsonb_build_object('version_id', version_uuid, 'revalidated_at', v_now,
    'snapshot', snapshot);
END;
$function$;

CREATE OR REPLACE FUNCTION public.rank_postseason_group(p_group jsonb, p_results jsonb, p_criterion integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE partitions JSONB; part JSONB; ranked JSONB := '[]';
BEGIN
  IF jsonb_array_length(p_group) < 2 THEN RETURN p_group; END IF;
  IF p_criterion > 4 THEN RAISE EXCEPTION 'Qualification lottery must be unique'; END IF;
  WITH metrics AS (
    SELECT t, CASE p_criterion
      WHEN 0 THEN (t->>'wins')::BIGINT
      WHEN 1 THEN (SELECT count(*) FROM jsonb_array_elements(p_results) r
        WHERE r->>'teamId' = t->>'teamId' AND (r->>'won')::BOOLEAN
          AND EXISTS (SELECT 1 FROM jsonb_array_elements(p_group) o WHERE o->>'teamId' = r->>'opponentId'))
      WHEN 2 THEN (t->>'conferenceWins')::BIGINT
      WHEN 3 THEN (t->>'differential')::BIGINT
      ELSE -(t->>'drawOrder')::BIGINT END AS n,
      greatest(1, CASE p_criterion
        WHEN 0 THEN (t->>'wins')::BIGINT + (t->>'losses')::BIGINT
        WHEN 1 THEN (SELECT count(*) FROM jsonb_array_elements(p_results) r
          WHERE r->>'teamId' = t->>'teamId'
            AND EXISTS (SELECT 1 FROM jsonb_array_elements(p_group) o WHERE o->>'teamId' = r->>'opponentId'))
        WHEN 2 THEN (t->>'conferenceGames')::BIGINT ELSE 1 END) AS d
    FROM jsonb_array_elements(p_group) t
  ), ordered AS (
    SELECT a.t, (SELECT count(*) FROM metrics b WHERE b.n * a.d > a.n * b.d) AS position
    FROM metrics a
  ), groups AS (
    SELECT position, jsonb_agg(t ORDER BY t->>'teamId') AS members FROM ordered GROUP BY position
  ) SELECT jsonb_agg(members ORDER BY position) INTO partitions FROM groups;
  IF jsonb_array_length(partitions) = 1 THEN
    RETURN public.rank_postseason_group(p_group, p_results, p_criterion + 1);
  END IF;
  FOR part IN SELECT value FROM jsonb_array_elements(partitions) LOOP
    ranked := ranked || public.rank_postseason_group(part, p_results, 1);
  END LOOP;
  RETURN ranked;
END;
$function$;

CREATE OR REPLACE FUNCTION public.release_roster_player(p_game_id uuid, p_player_id uuid, p_request_id uuid, p_contract_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  g public.games%ROWTYPE; s public.game_player_states%ROWTYPE;
  r public.game_runtime_contracts%ROWTYPE; a public.game_contract_agreements%ROWTYPE;
  c public.contracts%ROWTYPE; previous public.game_roster_releases%ROWTYPE;
  salaries JSONB := '{}'; origin TEXT := 'observed'; current_contract UUID; release_id UUID;
BEGIN
  IF auth.uid() IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  IF p_game_id IS NULL OR p_player_id IS NULL OR p_request_id IS NULL THEN
    RAISE EXCEPTION 'Release identifiers required';
  END IF;
  -- Same game-first lock order as trades, signing and simulation days.
  SELECT * INTO g FROM public.games WHERE id = p_game_id AND user_id = auth.uid()
    AND status = 'active' AND season_era_id = 'modern' AND season_year = 2026
    AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Owned active modern 2026 game required'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.game_contract_materializations WHERE game_id = p_game_id) THEN
    RAISE EXCEPTION 'Materialized contract coverage required';
  END IF;
  SELECT * INTO previous FROM public.game_roster_releases WHERE game_id = p_game_id AND request_id = p_request_id;
  IF FOUND THEN
    IF previous.player_id <> p_player_id OR previous.contract_id IS DISTINCT FROM p_contract_id THEN
      RAISE EXCEPTION 'Idempotency key reused with changed release payload';
    END IF;
    RETURN previous.id;
  END IF;
  SELECT * INTO s FROM public.game_player_states WHERE game_id = p_game_id AND player_id = p_player_id FOR UPDATE;
  IF NOT FOUND OR s.team_id IS DISTINCT FROM g.selected_team_id OR NOT s.is_active THEN
    RAISE EXCEPTION 'Player is not on the selected team active roster';
  END IF;
  SELECT * INTO r FROM public.game_active_runtime_contracts WHERE game_id = p_game_id AND player_id = p_player_id;
  IF FOUND THEN
    current_contract := r.id; origin := 'simulated';
    SELECT jsonb_object_agg(y::TEXT, CASE WHEN r.is_guaranteed IS false THEN 0 ELSE r.annual_salary END)
    INTO salaries FROM generate_series(GREATEST(g.season_year, r.start_year), r.end_year) y;
  ELSE
    SELECT * INTO a FROM public.game_contract_agreements WHERE game_id = p_game_id AND player_id = p_player_id;
    IF FOUND THEN
      current_contract := a.id;
      IF a.cap_treatment = 'standard-cap-and-matching' THEN
        IF NOT EXISTS (SELECT 1 FROM public.game_contract_seasons WHERE game_id = p_game_id
          AND agreement_id = a.id AND start_year = g.season_year AND salary_amount IS NOT NULL) THEN
          RAISE EXCEPTION 'Release salary coverage is incomplete';
        END IF;
        -- ponytail: retain known salaries with unknown/partial guarantees; no stretch or set-off in v1.
        SELECT jsonb_object_agg(start_year::TEXT, CASE WHEN guarantee_kind = 'not-guaranteed' THEN 0 ELSE salary_amount END)
        INTO salaries FROM public.game_contract_seasons
        WHERE game_id = p_game_id AND agreement_id = a.id AND start_year >= g.season_year
          AND salary_amount IS NOT NULL;
      END IF;
    ELSIF EXISTS (SELECT 1 FROM public.game_contract_identities WHERE game_id = p_game_id
      AND player_id = p_player_id AND cap_treatment = 'excluded-two-way') THEN
      current_contract := NULL;
    ELSE
      SELECT * INTO c FROM public.contracts WHERE game_id = p_game_id AND player_id = p_player_id;
      IF NOT FOUND OR (SELECT count(*) FROM public.contracts WHERE game_id = p_game_id AND player_id = p_player_id) <> 1 THEN
        RAISE EXCEPTION 'Release salary coverage is incomplete';
      END IF;
      current_contract := c.id;
      SELECT jsonb_object_agg(y::TEXT, CASE WHEN c.is_guaranteed IS false THEN 0 ELSE
        (ARRAY[c.salary_y1, c.salary_y2, c.salary_y3, c.salary_y4, c.salary_y5])[y - c.start_year + 1] END)
      INTO salaries FROM generate_series(GREATEST(g.season_year, c.start_year), c.end_year) y;
      IF EXISTS (SELECT 1 FROM jsonb_each(salaries) WHERE value = 'null'::JSONB) THEN
        RAISE EXCEPTION 'Release salary coverage is incomplete';
      END IF;
    END IF;
  END IF;
  IF current_contract IS DISTINCT FROM p_contract_id THEN RAISE EXCEPTION 'Player contract changed; refresh the roster'; END IF;
  IF EXISTS (SELECT 1 FROM jsonb_each_text(COALESCE(salaries, '{}'))
    WHERE value IS NULL OR value::NUMERIC < 0 OR value::NUMERIC > 9007199254740991) THEN
    RAISE EXCEPTION 'Release salary coverage is incomplete';
  END IF;
  INSERT INTO public.game_roster_releases(game_id, player_id, team_id, request_id, contract_id,
    contract_origin, salary_by_year, released_date)
  VALUES (p_game_id, p_player_id, g.selected_team_id, p_request_id, current_contract,
    origin, COALESCE(salaries, '{}'), g.simulation_date) RETURNING id INTO release_id;
  UPDATE public.game_runtime_contracts SET released_at = now() WHERE id = r.id;
  -- Legacy compatibility rows describe live contracts, unlike immutable imported snapshots.
  DELETE FROM public.contracts WHERE game_id = p_game_id AND player_id = p_player_id;
  UPDATE public.game_player_states SET team_id = NULL, updated_at = now() WHERE id = s.id;
  RETURN release_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.reserve_contract_snapshot_revalidation(p_source text, p_team text, p_season text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF char_length(trim(p_source)) = 0 OR p_team !~ '^[A-Z]{2,3}$' OR p_season !~ '^\d{4}-\d{2}$' THEN
    RAISE EXCEPTION 'Invalid contract snapshot identity';
  END IF;
  RETURN nextval('contract_snapshot_revalidation_revision_seq');
END;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_due_free_agency_market(p_game_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  g public.games%ROWTYPE; player UUID; o public.free_agency_pending_offers%ROWTYPE;
  assessment RECORD; winner UUID; winner_team UUID; best NUMERIC; total INTEGER := 0;
BEGIN
  SELECT * INTO g FROM public.games WHERE id = p_game_id AND user_id = auth.uid()
    AND status = 'active' AND season_era_id = 'modern' AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Owned active modern game required'; END IF;
  -- Older due groups first, then player identity. Later groups see updated cap/roster.
  FOR player IN SELECT player_id FROM public.free_agency_pending_offers
    WHERE game_id = p_game_id AND owner_id = auth.uid() AND status = 'pending' AND due_date <= g.simulation_date
    GROUP BY player_id ORDER BY min(due_date), player_id
  LOOP
    winner := NULL; winner_team := NULL; best := NULL;
    FOR o IN SELECT * FROM public.free_agency_pending_offers
      WHERE game_id = p_game_id AND player_id = player AND owner_id = auth.uid()
        AND status = 'pending' AND due_date <= g.simulation_date ORDER BY id FOR UPDATE
    LOOP
      SELECT * INTO STRICT assessment FROM public.assess_free_agency_offer(p_game_id, o.id);
      IF assessment.rejection_reason IS NOT NULL THEN
        UPDATE public.free_agency_pending_offers SET status = 'rejected', resolved_at = clock_timestamp(),
          resolved_date = g.simulation_date, resolution_reason = 'offer_no_longer_legal',
          resolution_detail = assessment.rejection_reason WHERE id = o.id;
      ELSIF winner IS NULL OR assessment.score > best OR (assessment.score = best AND (o.team_id, o.id) < (winner_team, winner)) THEN
        winner := o.id; winner_team := o.team_id; best := assessment.score;
      END IF;
    END LOOP;
    IF winner IS NOT NULL THEN
      PERFORM public.resolve_free_agency_offer(p_game_id, winner);
      total := total + 1;
    END IF;
  END LOOP;
  RETURN total;
END;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_free_agency_offer(p_game_id uuid, p_offer_id uuid)
 RETURNS free_agency_pending_offers
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  g public.games%ROWTYPE; o public.free_agency_pending_offers%ROWTYPE;
  assessment RECORD; contract_id UUID; resolved_time TIMESTAMPTZ := clock_timestamp(); updated_count INTEGER;
BEGIN
  SELECT * INTO g FROM public.games WHERE id = p_game_id AND user_id = auth.uid()
    AND status = 'active' AND season_era_id = 'modern' AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Owned active modern game required'; END IF;
  SELECT * INTO o FROM public.free_agency_pending_offers
  WHERE id = p_offer_id AND game_id = p_game_id AND owner_id = auth.uid() FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Owned game offer not found'; END IF;
  IF o.status = 'accepted' THEN
    IF NOT EXISTS (SELECT 1 FROM public.game_runtime_contracts r WHERE r.id = o.resolved_contract_id
      AND r.game_id = p_game_id AND r.player_id = o.player_id AND r.source_offer_id = o.id) THEN
      RAISE EXCEPTION 'Accepted offer resolution record is inconsistent';
    END IF;
    RETURN o;
  ELSIF o.status = 'rejected' THEN RETURN o;
  END IF;
  PERFORM 1 FROM public.game_player_states WHERE game_id = p_game_id AND player_id = o.player_id FOR UPDATE;
  SELECT * INTO STRICT assessment FROM public.assess_free_agency_offer(p_game_id, p_offer_id);
  IF assessment.rejection_reason IS NOT NULL THEN RAISE EXCEPTION '%', assessment.rejection_reason; END IF;

  INSERT INTO public.game_runtime_contracts(game_id, player_id, origin_kind, start_year, end_year,
    annual_salary, is_player_option, is_team_option, is_guaranteed, source_offer_id)
  VALUES (p_game_id, o.player_id, 'simulated-agreement', g.season_year, g.season_year + o.years - 1,
    o.annual_salary, false, false, NULL, o.id) RETURNING id INTO contract_id;
  UPDATE public.game_player_states SET team_id = o.team_id, updated_at = now()
  WHERE game_id = p_game_id AND player_id = o.player_id AND team_id IS NULL AND is_active;
  GET DIAGNOSTICS updated_count = ROW_COUNT;
  IF updated_count <> 1 THEN RAISE EXCEPTION 'Roster assignment changed during offer resolution'; END IF;
  UPDATE public.free_agency_pending_offers SET status = 'accepted', resolved_at = resolved_time,
    resolved_date = g.simulation_date, resolution_reason = 'selected_offer_accepted', resolved_contract_id = contract_id
  WHERE id = p_offer_id RETURNING * INTO o;
  UPDATE public.free_agency_pending_offers SET status = 'rejected', resolved_at = resolved_time,
    resolved_date = g.simulation_date, resolution_reason = 'another_offer_accepted'
  WHERE game_id = p_game_id AND player_id = o.player_id AND status = 'pending';
  RETURN o;
END;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_offseason_player_options(p_game_id uuid, p_season_year integer)
 RETURNS SETOF game_offseason_player_options
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
  -- Reuse authentication, game lock, entry checks and strict snapshot revalidation.
  -- Explicit resolution may prepare missing 054 rows, but never changes existing rows or team decisions.
  PERFORM public.prepare_offseason_contracts(p_game_id,p_season_year);
  WITH salaries AS (
    SELECT l.*,CASE
      WHEN l.evidence->'runtime'<>'null'::JSONB THEN (l.evidence->'runtime'->>'annual_salary')::BIGINT
      WHEN l.evidence->'identity'<>'null'::JSONB OR l.evidence->'agreement'<>'null'::JSONB THEN
        CASE WHEN c.matches=1 THEN c.salary END
      ELSE (l.evidence->'legacy'->>('salary_y'||(p_season_year+1-(l.evidence->'legacy'->>'start_year')::INTEGER)))::BIGINT
      END current_salary
    FROM public.game_offseason_contracts l
    CROSS JOIN LATERAL (
      SELECT count(*) matches,min((s->>'salary_amount')::BIGINT) salary
      FROM jsonb_array_elements(l.evidence->'seasons') s
      WHERE (s->>'start_year')::INTEGER=p_season_year
    ) c
    WHERE l.game_id=p_game_id AND l.season_year=p_season_year AND l.classification='player_option'
  )
  INSERT INTO public.game_offseason_player_options
    (game_id,season_year,player_id,team_id,current_salary,next_salary,decision,reason,evidence)
    SELECT game_id,season_year,player_id,team_id,current_salary,next_salary,
      CASE WHEN next_salary>=current_salary THEN 'exercise' ELSE 'decline' END,
      CASE WHEN next_salary>=current_salary THEN 'salary_not_lower' ELSE 'salary_lower' END,evidence
    FROM salaries WHERE current_salary>=0 AND next_salary>=0
    ON CONFLICT (game_id,season_year,player_id) DO NOTHING;
  RETURN QUERY SELECT * FROM public.game_offseason_player_options
    WHERE game_id=p_game_id AND season_year=p_season_year ORDER BY player_id;
END $function$;

CREATE OR REPLACE FUNCTION public.rollback_seed_game_data(p_game_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_game games%ROWTYPE;
BEGIN
  SELECT * INTO v_game
  FROM games
  WHERE id = p_game_id
    AND user_id = auth.uid()
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'rollback_seed_game_data aborted: game % is not owned by the caller', p_game_id;
  END IF;
  IF v_game.status <> 'initializing' OR v_game.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'rollback_seed_game_data aborted: game % is not initializing', p_game_id;
  END IF;

  DELETE FROM game_player_attributes WHERE game_id = p_game_id;
  DELETE FROM game_attribute_materializations WHERE game_id = p_game_id;
  DELETE FROM free_agency_imports WHERE game_id = p_game_id;
  DELETE FROM free_agency_availability_enrollments WHERE game_id = p_game_id;
  DELETE FROM game_contract_provenance WHERE game_id = p_game_id;
  DELETE FROM game_contract_seasons WHERE game_id = p_game_id;
  DELETE FROM game_contract_identities WHERE game_id = p_game_id;
  DELETE FROM game_contract_agreements WHERE game_id = p_game_id;
  DELETE FROM game_contract_materializations WHERE game_id = p_game_id;
  DELETE FROM contracts WHERE game_id = p_game_id;
  DELETE FROM game_player_states WHERE game_id = p_game_id;
  DELETE FROM game_pick_inventory WHERE game_id = p_game_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.seed_game_data(p_game_id uuid, p_team_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_game games%ROWTYPE; v_roster_count INTEGER; v_contract_count INTEGER;
BEGIN
  SELECT * INTO v_game FROM games g WHERE g.id = p_game_id AND g.selected_team_id = p_team_id
    AND g.user_id = auth.uid() AND g.status = 'initializing' FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'seed_game_data aborted: game is not initializing, not owned by the caller, or selected team does not match'; END IF;
  IF v_game.season_era_id <> 'modern' THEN
    IF NOT EXISTS (SELECT 1 FROM historical_roster_templates WHERE season_year = v_game.season_year) THEN
      RAISE EXCEPTION 'seed_game_data aborted: historical templates for season % are not loaded', v_game.season_year;
    END IF;
    INSERT INTO game_player_states(game_id, player_id, team_id, is_active)
      SELECT p_game_id, player_id, team_id, is_active FROM historical_roster_templates
      WHERE season_year = v_game.season_year ON CONFLICT (game_id, player_id) DO NOTHING;
    INSERT INTO contracts(game_id, player_id, team_id, start_year, end_year, salary_y1, salary_y2,
      salary_y3, salary_y4, salary_y5, is_player_option, is_team_option, is_guaranteed)
      SELECT p_game_id, player_id, team_id, start_year, end_year, salary_y1, salary_y2, salary_y3,
        salary_y4, salary_y5, is_player_option, is_team_option, is_guaranteed
      FROM historical_contract_templates WHERE season_year = v_game.season_year
      ON CONFLICT (game_id, player_id) DO NOTHING;
    SELECT count(*) INTO v_roster_count FROM game_player_states WHERE game_id = p_game_id;
    SELECT count(*) INTO v_contract_count FROM contracts WHERE game_id = p_game_id;
    IF v_roster_count = 0 OR v_contract_count <> v_roster_count THEN
      RAISE EXCEPTION 'seed_game_data aborted: incomplete historical snapshot';
    END IF;
  ELSE
    INSERT INTO game_player_states(game_id, player_id, team_id)
      SELECT p_game_id, id, team_id FROM players WHERE team_id IS NOT NULL
      ON CONFLICT (game_id, player_id) DO NOTHING;
    IF EXISTS (SELECT 1 FROM contracts WHERE game_id = p_game_id) THEN
      RAISE EXCEPTION 'seed_game_data refuses legacy contracts for modern games';
    END IF;
  END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION public.seed_game_pick_inventory(p_game_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_season_year INTEGER;
BEGIN
  SELECT season_year INTO v_season_year FROM games
  WHERE id = p_game_id AND user_id = auth.uid();
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Game not found or access denied';
  END IF;
  INSERT INTO draft_picks (draft_year, draft_round, original_team_id)
  SELECT y.draft_year, r.draft_round, t.id
  FROM generate_series(v_season_year, v_season_year + 6) AS y(draft_year)
  CROSS JOIN (VALUES (1), (2)) AS r(draft_round)
  CROSS JOIN teams t
  ON CONFLICT (draft_year, draft_round, original_team_id) DO NOTHING;
  INSERT INTO game_pick_inventory (game_id, draft_pick_id, owner_team_id)
  SELECT p_game_id, p.id, p.original_team_id FROM draft_picks p
  WHERE p.draft_year BETWEEN v_season_year AND v_season_year + 6
  ON CONFLICT (game_id, draft_pick_id) DO NOTHING;
END;
$function$;

CREATE OR REPLACE FUNCTION public.seed_game_pick_inventory_after_game()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_season_year INTEGER;
BEGIN
  SELECT season_year INTO v_season_year FROM games WHERE id = NEW.id;
  INSERT INTO draft_picks (draft_year, draft_round, original_team_id)
  SELECT y.draft_year, r.draft_round, t.id
  FROM generate_series(v_season_year, v_season_year + 6) AS y(draft_year)
  CROSS JOIN (VALUES (1), (2)) AS r(draft_round)
  CROSS JOIN teams t
  ON CONFLICT (draft_year, draft_round, original_team_id) DO NOTHING;
  INSERT INTO game_pick_inventory (game_id, draft_pick_id, owner_team_id)
  SELECT NEW.id, p.id, p.original_team_id FROM draft_picks p
  WHERE p.draft_year BETWEEN v_season_year AND v_season_year + 6
  ON CONFLICT (game_id, draft_pick_id) DO NOTHING;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.simulate_fixture_box_score(p_fixture_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  fixture public.scheduled_games%ROWTYPE;
  career public.games%ROWTYPE;
  home JSONB;
  away JSONB;
  available INTEGER;
  result JSONB;
BEGIN
  SELECT * INTO fixture FROM public.scheduled_games WHERE id = p_fixture_id FOR UPDATE;
  SELECT * INTO career FROM public.games WHERE id = fixture.game_id AND user_id = auth.uid()
    AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'Game not found or access denied'; END IF;
  IF fixture.status <> 'scheduled' THEN RAISE EXCEPTION 'Fixture already completed'; END IF;
  -- Legacy careers keep their established score-only simulation; never backfill past results.
  IF career.season_era_id <> 'modern' OR NOT EXISTS (
    SELECT 1 FROM public.game_attribute_materializations
      WHERE game_id = career.id AND season_year = career.season_year
  ) THEN RETURN NULL; END IF;
  SELECT count(*) INTO available FROM public.game_player_states s
    WHERE s.game_id = career.id AND s.team_id IN (fixture.home_team_id, fixture.away_team_id)
      AND s.is_active AND NOT s.is_injured;
  SELECT jsonb_agg(jsonb_build_object('playerId', s.player_id, 'playerName', p.full_name,
    'attributes', a.attributes) ORDER BY
    ((a.attributes->>'closeShot')::INTEGER + (a.attributes->>'threePointShot')::INTEGER
      + (a.attributes->>'interiorDefense')::INTEGER) DESC, s.player_id)
    FILTER (WHERE s.team_id = fixture.home_team_id),
    jsonb_agg(jsonb_build_object('playerId', s.player_id, 'playerName', p.full_name,
    'attributes', a.attributes) ORDER BY
    ((a.attributes->>'closeShot')::INTEGER + (a.attributes->>'threePointShot')::INTEGER
      + (a.attributes->>'interiorDefense')::INTEGER) DESC, s.player_id)
    FILTER (WHERE s.team_id = fixture.away_team_id)
  INTO home, away FROM public.game_player_states s
    JOIN public.players p ON p.id = s.player_id
    JOIN public.game_player_attributes a ON a.game_id = s.game_id AND a.player_id = s.player_id
      AND a.season_year = career.season_year
    WHERE s.game_id = career.id AND s.team_id IN (fixture.home_team_id, fixture.away_team_id)
      AND s.is_active AND NOT s.is_injured;
  IF coalesce(jsonb_array_length(home),0) + coalesce(jsonb_array_length(away),0) <> available
    THEN RAISE EXCEPTION 'Player attribute coverage is incomplete'; END IF;
  IF coalesce(jsonb_array_length(home),0) < 5 OR coalesce(jsonb_array_length(away),0) < 5
    THEN RAISE EXCEPTION 'At least five available players per team are required'; END IF;
  -- A career roster can include extra two-way players; dress at most fifteen per fixture.
  SELECT jsonb_agg(r ORDER BY n) INTO home
    FROM jsonb_array_elements(home) WITH ORDINALITY AS r(r,n) WHERE n <= 15;
  SELECT jsonb_agg(r ORDER BY n) INTO away
    FROM jsonb_array_elements(away) WITH ORDINALITY AS r(r,n) WHERE n <= 15;
  result := public.simulate_possession_game(home, away,
    career.id::TEXT || ':' || fixture.game_date::TEXT || ':' || fixture.home_team_id::TEXT || ':' || fixture.away_team_id::TEXT);
  INSERT INTO public.game_box_scores(game_id, scheduled_game_id, payload)
    VALUES (career.id, fixture.id, result);
  RETURN result;
END;
$function$;

CREATE OR REPLACE FUNCTION public.simulate_possession_game(p_home jsonb, p_away jsonb, p_seed text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  roster JSONB := p_home || p_away;
  home_count INTEGER := jsonb_array_length(p_home);
  player_count INTEGER := jsonb_array_length(roster);
  attrs JSONB[];
  -- seconds, FGM, FGA, 3PM, 3PA, FTM, FTA, OREB, DREB, AST, STL, BLK, TOV, PF, PTS.
  stats INTEGER[][] := array_fill(0, ARRAY[player_count, 15]);
  quality NUMERIC[] := array_fill(0::NUMERIC, ARRAY[player_count]);
  depth_rank INTEGER[];
  rotation_weight DOUBLE PRECISION[] := array_fill(0::DOUBLE PRECISION, ARRAY[player_count]);
  home_lineup INTEGER[];
  away_lineup INTEGER[];
  offense INTEGER[];
  defense INTEGER[];
  period INTEGER := 1;
  pairs INTEGER;
  duration INTEGER;
  tick INTEGER;
  side INTEGER;
  i INTEGER;
  shooter INTEGER;
  defender INTEGER;
  passer INTEGER;
  rebounder INTEGER;
  attempt INTEGER;
  shot_value INTEGER;
  free_throws INTEGER;
  ft INTEGER;
  home_score INTEGER := 0;
  away_score INTEGER := 0;
  weight DOUBLE PRECISION;
  target DOUBLE PRECISION;
  probability DOUBLE PRECISION;
  total_weight DOUBLE PRECISION;
  shot_attribute TEXT;
  draw_seed TEXT;
  made BOOLEAN;
  foul BOOLEAN;
  blocked BOOLEAN;
  missed BOOLEAN;
  rows JSONB := '[]';
BEGIN
  IF home_count NOT BETWEEN 5 AND 15 OR jsonb_array_length(p_away) NOT BETWEEN 5 AND 15
     OR (SELECT count(DISTINCT r->>'playerId') FROM jsonb_array_elements(roster) r) <> player_count
     OR EXISTS (SELECT 1 FROM jsonb_array_elements(roster) r
       WHERE NOT coalesce(public.is_valid_player_attributes(r->'attributes'), false)
         OR nullif(r->>'playerName', '') IS NULL) THEN
    RAISE EXCEPTION 'Invalid possession simulation roster';
  END IF;
  SELECT array_agg(r->'attributes' ORDER BY n) INTO attrs
    FROM jsonb_array_elements(roster) WITH ORDINALITY AS r(r, n);
  FOR i IN 1..player_count LOOP
    quality[i] := (SELECT avg(value::NUMERIC) FROM jsonb_each_text(attrs[i]));
  END LOOP;
  SELECT array_agg(depth::INTEGER ORDER BY idx) INTO depth_rank FROM (
    SELECT idx, row_number() OVER (PARTITION BY (idx <= home_count) ORDER BY quality[idx] DESC, idx) AS depth
    FROM generate_series(1, player_count) idx
  ) ranked;
  FOR i IN 1..player_count LOOP
    rotation_weight[i] := CASE WHEN depth_rank[i] <= 5 THEN 2 ELSE 1 END
      * (0.75 + (attrs[i]->>'stamina')::NUMERIC / 198) * (0.5 + quality[i] / 198);
  END LOOP;

  LOOP
    pairs := CASE WHEN period <= 4 THEN 25 ELSE 11 END;
    duration := CASE WHEN period <= 4 THEN 720 ELSE 300 END;
    FOR tick IN 1..pairs LOOP
      -- Weighted playing time gives the first unit roughly twice the bench minutes.
      -- shortcut: foul-outs apply at shift boundaries; use event-clock substitutions for play-by-play.
      IF tick = 1 OR (tick - 1) % 3 = 0 THEN
        SELECT array_agg(idx) INTO home_lineup FROM (
          SELECT idx FROM generate_series(1, home_count) idx
          ORDER BY (stats[idx][14] >= 6), (depth_rank[idx] > 10),
            stats[idx][1] / rotation_weight[idx], depth_rank[idx] LIMIT 5
        ) selected;
        SELECT array_agg(idx) INTO away_lineup FROM (
          SELECT idx FROM generate_series(home_count + 1, player_count) idx
          ORDER BY (stats[idx][14] >= 6), (depth_rank[idx] > 10),
            stats[idx][1] / rotation_weight[idx], depth_rank[idx] LIMIT 5
        ) selected;
      END IF;
      FOREACH i IN ARRAY home_lineup || away_lineup LOOP
        stats[i][1] := stats[i][1] + (tick * duration / pairs - (tick - 1) * duration / pairs);
      END LOOP;

      FOR side IN 0..1 LOOP
        offense := CASE WHEN side = 0 THEN home_lineup ELSE away_lineup END;
        defense := CASE WHEN side = 0 THEN away_lineup ELSE home_lineup END;
        attempt := 0;
        LOOP
          attempt := attempt + 1;
          IF attempt > 100 THEN RAISE EXCEPTION 'Possession did not terminate'; END IF;
          draw_seed := p_seed || ':' || period || ':' || tick || ':' || side || ':' || attempt;
          total_weight := 0;
          FOREACH i IN ARRAY offense LOOP
            total_weight := total_weight + 30 + (attrs[i]->>'closeShot')::INTEGER
              + (attrs[i]->>'threePointShot')::INTEGER + (attrs[i]->>'drawFoul')::INTEGER;
          END LOOP;
          target := public.possession_random(draw_seed, 1) * total_weight;
          shooter := offense[1];
          FOREACH i IN ARRAY offense LOOP
            target := target - (30 + (attrs[i]->>'closeShot')::INTEGER
              + (attrs[i]->>'threePointShot')::INTEGER + (attrs[i]->>'drawFoul')::INTEGER);
            IF target < 0 THEN shooter := i; EXIT; END IF;
          END LOOP;
          defender := defense[1 + floor(public.possession_random(draw_seed, 2) * 5)::INTEGER];
          probability := 0.14 + ((attrs[defender]->>'steal')::INTEGER
            - ((attrs[shooter]->>'ballHandle')::INTEGER + (attrs[shooter]->>'passAccuracy')::INTEGER) / 2.0) * 0.001;
          IF public.possession_random(draw_seed, 3) < probability THEN
            stats[shooter][13] := stats[shooter][13] + 1;
            IF public.possession_random(draw_seed, 4) < 0.45 + (attrs[defender]->>'steal')::INTEGER * 0.003 THEN
              stats[defender][11] := stats[defender][11] + 1;
            END IF;
            EXIT;
          END IF;
          -- Low-rated outside shooters should not take a forced baseline share of threes.
          shot_value := CASE WHEN public.possession_random(draw_seed, 5)
            < least(0.65, greatest(0, ((attrs[shooter]->>'threePointShot')::INTEGER - 35) * 0.01)) THEN 3 ELSE 2 END;
          shot_attribute := CASE WHEN shot_value = 3 THEN 'threePointShot'
            WHEN public.possession_random(draw_seed, 6) < 0.7 THEN 'closeShot' ELSE 'midRangeShot' END;
          foul := public.possession_random(draw_seed, 7) < 0.04 + (attrs[shooter]->>'drawFoul')::INTEGER * 0.001;
          blocked := NOT foul AND public.possession_random(draw_seed, 8)
            < 0.005 + (attrs[defender]->>'block')::INTEGER * CASE WHEN shot_value = 3 THEN 0.0003 ELSE 0.0007 END;
          probability := CASE WHEN shot_value = 3 THEN
              0.12 + (attrs[shooter]->>'threePointShot')::INTEGER * 0.0042
                - (attrs[defender]->>'perimeterDefense')::INTEGER * 0.001
            ELSE CASE shot_attribute WHEN 'closeShot' THEN 0.35 ELSE 0.24 END
              + (attrs[shooter]->>shot_attribute)::INTEGER * 0.004
              - (attrs[defender]->>'interiorDefense')::INTEGER * 0.0015 END
            + CASE WHEN side = 0 THEN 0.012 ELSE 0 END;
          made := NOT blocked AND public.possession_random(draw_seed, 9) < probability;
          IF NOT foul OR made THEN
            stats[shooter][3] := stats[shooter][3] + 1;
            IF shot_value = 3 THEN stats[shooter][5] := stats[shooter][5] + 1; END IF;
          END IF;
          IF blocked THEN stats[defender][12] := stats[defender][12] + 1; END IF;
          IF made THEN
            stats[shooter][2] := stats[shooter][2] + 1;
            IF shot_value = 3 THEN stats[shooter][4] := stats[shooter][4] + 1; END IF;
            stats[shooter][15] := stats[shooter][15] + shot_value;
            SELECT idx INTO passer FROM unnest(offense) idx WHERE idx <> shooter
              ORDER BY public.possession_random(draw_seed || ':' || idx, 10)
                / (20 + (attrs[idx]->>'passAccuracy')::INTEGER) LIMIT 1;
            IF public.possession_random(draw_seed, 11) < 0.3 + (attrs[passer]->>'passAccuracy')::INTEGER * 0.005 THEN
              stats[passer][10] := stats[passer][10] + 1;
            END IF;
          END IF;
          missed := NOT made;
          IF foul THEN
            stats[defender][14] := stats[defender][14] + 1;
            free_throws := CASE WHEN made THEN 1 ELSE shot_value END;
            FOR ft IN 1..free_throws LOOP
              stats[shooter][7] := stats[shooter][7] + 1;
              missed := public.possession_random(draw_seed, 11 + ft)
                >= 0.4 + (attrs[shooter]->>'freeThrow')::INTEGER * 0.0055;
              IF NOT missed THEN
                stats[shooter][6] := stats[shooter][6] + 1;
                stats[shooter][15] := stats[shooter][15] + 1;
              END IF;
            END LOOP;
          END IF;
          IF NOT missed THEN EXIT; END IF;
          total_weight := 0;
          FOREACH i IN ARRAY offense || defense LOOP
            total_weight := total_weight + CASE WHEN i = ANY(offense)
              THEN 10 + (attrs[i]->>'offensiveRebound')::INTEGER
              ELSE 60 + (attrs[i]->>'defensiveRebound')::INTEGER * 2.5 END;
          END LOOP;
          target := public.possession_random(draw_seed, 15) * total_weight;
          rebounder := defense[1];
          FOREACH i IN ARRAY offense || defense LOOP
            weight := CASE WHEN i = ANY(offense) THEN 10 + (attrs[i]->>'offensiveRebound')::INTEGER
              ELSE 60 + (attrs[i]->>'defensiveRebound')::INTEGER * 2.5 END;
            target := target - weight;
            IF target < 0 THEN rebounder := i; EXIT; END IF;
          END LOOP;
          IF rebounder = ANY(defense) THEN
            stats[rebounder][9] := stats[rebounder][9] + 1;
            EXIT;
          END IF;
          stats[rebounder][8] := stats[rebounder][8] + 1;
        END LOOP;
      END LOOP;
    END LOOP;
    IF period >= 4 THEN
      home_score := 0; away_score := 0;
      FOR i IN 1..player_count LOOP
        IF i <= home_count THEN home_score := home_score + stats[i][15];
        ELSE away_score := away_score + stats[i][15]; END IF;
      END LOOP;
      IF home_score <> away_score THEN EXIT; END IF;
      IF period >= 24 THEN RAISE EXCEPTION 'Overtime limit exceeded'; END IF;
    END IF;
    period := period + 1;
  END LOOP;
  FOR i IN 1..player_count LOOP
    rows := rows || jsonb_build_array(jsonb_build_object(
      'playerId', roster->(i-1)->>'playerId', 'playerName', roster->(i-1)->>'playerName',
      'side', CASE WHEN i <= home_count THEN 'home' ELSE 'away' END,
      'seconds', stats[i][1], 'fieldGoalsMade', stats[i][2], 'fieldGoalsAttempted', stats[i][3],
      'threePointersMade', stats[i][4], 'threePointersAttempted', stats[i][5],
      'freeThrowsMade', stats[i][6], 'freeThrowsAttempted', stats[i][7],
      'offensiveRebounds', stats[i][8], 'defensiveRebounds', stats[i][9],
      'assists', stats[i][10], 'steals', stats[i][11], 'blocks', stats[i][12],
      'turnovers', stats[i][13], 'personalFouls', stats[i][14], 'points', stats[i][15]));
  END LOOP;
  RETURN jsonb_build_object('engineVersion', 'possessions-v2', 'overtimes', period - 4,
    'homeScore', home_score, 'awayScore', away_score, 'players', rows);
END;
$function$;

CREATE OR REPLACE FUNCTION public.store_contract_source_snapshot(p_source text, p_team text, p_season text, p_source_url text, p_observed_at timestamp with time zone, p_fetched_at timestamp with time zone, p_revalidation_revision bigint, p_content_hash text, p_payload jsonb)
 RETURNS TABLE(version_id uuid, source text, team text, season text, content_hash text, observed_at timestamp with time zone, stored_at timestamp with time zone, revalidated_at timestamp with time zone, payload jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_version_id UUID;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(p_source || ':' || p_team || ':' || p_season, 0));

  INSERT INTO contract_source_snapshot_versions (
    source, team, season, source_url, observed_at, fetched_at, content_hash, payload
  ) VALUES (
    p_source, p_team, p_season, p_source_url, p_observed_at, p_fetched_at, p_content_hash, p_payload
  )
  ON CONFLICT ON CONSTRAINT contract_source_snapshot_versions_content_unique DO NOTHING
  RETURNING id INTO v_version_id;

  IF v_version_id IS NULL THEN
    SELECT v.id INTO v_version_id
    FROM contract_source_snapshot_versions v
    WHERE v.source = p_source AND v.team = p_team AND v.season = p_season
      AND v.content_hash = p_content_hash;
  END IF;

  INSERT INTO current_contract_source_snapshots (
    source, team, season, version_id, revalidated_at, revalidation_revision
  )
  VALUES (p_source, p_team, p_season, v_version_id, p_fetched_at, p_revalidation_revision)
  ON CONFLICT ON CONSTRAINT current_contract_source_snapshots_pkey DO UPDATE SET
    version_id = EXCLUDED.version_id,
    revalidated_at = EXCLUDED.revalidated_at,
    revalidation_revision = EXCLUDED.revalidation_revision
  WHERE EXCLUDED.revalidation_revision > current_contract_source_snapshots.revalidation_revision;

  RETURN QUERY
  SELECT v.id, v.source, v.team, v.season, v.content_hash, v.observed_at, v.stored_at,
    c.revalidated_at, v.payload
  FROM current_contract_source_snapshots c
  JOIN contract_source_snapshot_versions v ON v.id = c.version_id
  WHERE c.source = p_source AND c.team = p_team AND c.season = p_season;
END;
$function$;

CREATE OR REPLACE FUNCTION public.submit_free_agency_offer(p_game_id uuid, p_player_id uuid, p_request_id uuid, p_season text, p_annual_salary bigint, p_years integer)
 RETURNS free_agency_pending_offers
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  g public.games%ROWTYPE; existing public.free_agency_pending_offers%ROWTYPE;
  result public.free_agency_pending_offers%ROWTYPE; f RECORD;
BEGIN
  IF auth.uid() IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_request_id IS NULL OR p_player_id IS NULL OR p_game_id IS NULL
    OR p_annual_salary IS NULL OR p_annual_salary <= 0 OR p_annual_salary > 9007199254740991
    OR p_years IS NULL OR p_years NOT BETWEEN 1 AND 5 OR p_season IS NULL OR p_season !~ '^\d{4}-\d{2}$'
    OR split_part(p_season, '-', 2)::INTEGER <> (split_part(p_season, '-', 1)::INTEGER + 1) % 100 THEN
    RAISE EXCEPTION 'Invalid offer terms';
  END IF;
  SELECT * INTO g FROM public.games WHERE id = p_game_id AND user_id = auth.uid()
    AND status = 'active' AND season_era_id = 'modern' AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Owned active game required'; END IF;
  SELECT * INTO existing FROM public.free_agency_pending_offers
  WHERE owner_id = auth.uid() AND game_id = p_game_id AND request_id = p_request_id FOR UPDATE;
  IF FOUND THEN
    IF (existing.player_id, existing.team_id, existing.season, existing.annual_salary, existing.years)
      IS DISTINCT FROM (p_player_id, g.selected_team_id, p_season, p_annual_salary, p_years) THEN
      RAISE EXCEPTION 'Idempotency key reused with changed offer payload';
    END IF;
    IF existing.status <> 'pending' THEN RAISE EXCEPTION 'Offer request has already been resolved'; END IF;
    RETURN existing;
  END IF;
  PERFORM 1 FROM public.game_player_states WHERE game_id = p_game_id AND player_id = p_player_id FOR UPDATE;
  IF NOT public.is_available_free_agent(p_game_id, p_player_id) THEN
    RAISE EXCEPTION 'Explicitly enrolled active teamless player without a game agreement required';
  END IF;
  SELECT * INTO STRICT f FROM public.get_free_agency_financial_context(p_game_id, p_player_id);
  IF p_season <> format('%s-%s', f.season_year, right((f.season_year + 1)::TEXT, 2)) OR p_season <> '2026-27' THEN
    RAISE EXCEPTION 'Offer season must match the supported game financial season';
  END IF;
  IF p_annual_salary < f.minimum_salary OR p_annual_salary > f.maximum_salary THEN RAISE EXCEPTION 'Salary outside verified minimum and maximum'; END IF;
  IF f.roster_count + 1 > 15 THEN RAISE EXCEPTION 'Roster maximum reached'; END IF;
  IF p_annual_salary > f.cap_room AND p_annual_salary <> f.minimum_salary THEN RAISE EXCEPTION 'Offer exceeds cap room'; END IF;
  INSERT INTO public.free_agency_pending_offers(request_id, owner_id, game_id, player_id, team_id, season, annual_salary, years, due_date)
  VALUES (p_request_id, auth.uid(), p_game_id, p_player_id, f.selected_team_id, p_season, p_annual_salary, p_years, f.simulation_date + 1)
  RETURNING * INTO result;
  RETURN result;
END;
$function$;

