CREATE VIEW public."game_active_runtime_contracts" WITH (security_invoker=true) AS  SELECT id,
    game_id,
    player_id,
    origin_kind,
    start_year,
    end_year,
    annual_salary,
    is_player_option,
    is_team_option,
    is_guaranteed,
    created_at,
    source_offer_id,
    released_at
   FROM game_runtime_contracts
  WHERE released_at IS NULL;

